// Classes and the subsystems hanging off them: witch patrons and lessons,
// familiar and master abilities.

// Witch patrons (Player Core). Each determines the witch's spellcasting tradition, trained skill,
// initial lesson (a bonus hex + familiar spell granted at 1st level), and a unique familiar ability.
export const PATRONS = [
  { key: 'faiths-flamekeeper', name: "Faith's Flamekeeper", tradition: 'Divine', patronSkill: 'Religion',
    desc: 'Your patron contacted you in a moment your willpower was close to sputtering out. Their reassuring presence was like breath and kindling bringing an ember back aflame, their magic giving you the strength to carry on and bring others to your cause. Your patron is likely a divine being like an angel or aeon acting covertly, though the possibility exists they might be a more sinister entity, using you to unknown ends.',
    lessonName: "Lesson of Fervor's Grasp", initialHex: 'Stoke the Heart', initialFamiliarSpell: 'Command',
    familiarAbilityName: 'Familiar of Restored Spirit', familiarAbilityDesc: 'Whenever you Cast or Sustain a hex, one willing creature within 15 feet of your familiar gains temporary Hit Points equal to 2 plus half your level, lasting until the start of your next turn.' },
  { key: 'inscribed-one', name: 'The Inscribed One', tradition: 'Arcane', patronSkill: 'Arcana',
    desc: 'No words passed your patron’s lips in the moment you met; instead, words and glyphs danced across their skin while symbols and numbers swam in the depths of their eyes, spelling out their will in a torrent of words and wisdom. Your patron might be a powerful archmage, or even one of their abandoned artifacts, searching for a successor.',
    lessonName: "Lesson of Glyph's Supremacy", initialHex: 'Discern Secrets', initialFamiliarSpell: 'Runic Weapon',
    familiarAbilityName: 'Familiar of Flowing Script', familiarAbilityDesc: "Whenever you Cast or Sustain a hex, shifting letter-like patterns across your familiar's body cause a distraction: until the start of your next turn, your familiar can provide flanking for you and your allies as though it could attack and had 5-foot reach (a visual effect only)." },
  { key: 'the-resentment', name: 'The Resentment', tradition: 'Occult', patronSkill: 'Occultism',
    desc: "A single feeling radiated from your patron in the moment you met them, as palpable as heat from a fire: the desire to see every tall poppy felled and every proud nail hammered down, whether to righteously bring justice for small folk or the base urge to see the powerful defeated. Your patron is likely far from the upper echelons of its kind, such as a hag ousted from its coven or a quasi-divinity or a lower-rank demon. This leaves it only subtler and weaker tools to see its ends met: curses, hexes, and you.",
    lessonName: "Lesson of Strength's Impermanence", initialHex: 'Evil Eye', initialFamiliarSpell: 'Enfeeble',
    familiarAbilityName: 'Familiar of Ongoing Misery', familiarAbilityDesc: 'Whenever you Cast or Sustain a hex, your familiar can curse a creature within 15 feet of it (a curse effect), extending the duration of any of its timed negative conditions by 1 round. This doesn\'t prevent those conditions from ending early by other means.' },
  { key: 'silence-in-snow', name: 'Silence in Snow', tradition: 'Primal', patronSkill: 'Nature',
    desc: 'Bitter cold heralded your patron’s appearance, in the depths of the winter solstice or on a frozen peak at the end of the world. Your patron might be a winter hag, ice yai, or other spirit of the cold, but one thing is clear as ice—their power is not to be underestimated.',
    lessonName: "Lesson of Winter's Chill", initialHex: 'Clinging Ice', initialFamiliarSpell: 'Gust of Wind',
    familiarAbilityName: 'Familiar of Freezing Rime', familiarAbilityDesc: "Whenever you Cast or Sustain a hex, you can cause ice to form in a 5-foot burst centered on your familiar's space; those squares become difficult terrain until the start of your next turn." },
  { key: 'spinner-of-threads', name: 'Spinner of Threads', tradition: 'Occult', patronSkill: 'Occultism',
    desc: "You met your patron in a memory of an encounter yet to come or a premonition of something long since passed, as they untangled and re-spun the tapestry of time and fate. Was your patron a norn? A herald of a deity like Pharasma, Alseta, or Grandmother Spider? Could it even be a single individual appearing at three or more points in its timeline—multiple versions of the same being, parallel threads converging on a single moment?",
    lessonName: "Lesson of Fate's Vicissitudes", initialHex: 'Nudge Fate', initialFamiliarSpell: 'Sure Strike',
    familiarAbilityName: 'Familiar of Balanced Luck', familiarAbilityDesc: 'Whenever you Cast or Sustain a hex, one creature within 15 feet of your familiar gains your choice of a +1 status bonus or a -1 status penalty to AC until the start of your next turn.' },
  { key: 'starless-shadow', name: 'Starless Shadow', tradition: 'Occult', patronSkill: 'Occultism',
    desc: 'Your patron first contacted you at the witching hour, as your body lay paralyzed by sleep while your mind had yet to escape the waking world. Your patron might be a creature of the Netherworld or a long-forgotten spirit of twilight—all you remember of them are haunting eyes of moonlight, offering you power from the darkness.',
    lessonName: "Lesson of Night's Terrors", initialHex: 'Shroud of Night', initialFamiliarSpell: 'Fear',
    familiarAbilityName: 'Familiar of Stalking Night', familiarAbilityDesc: "Whenever you Cast or Sustain a hex while your familiar is adjacent to an enemy it is concealed from, hidden from, or undetected by, that enemy becomes frightened 1." },
  { key: 'wilding-steward', name: 'Wilding Steward', tradition: 'Primal', patronSkill: 'Nature',
    desc: 'When your patron appeared before you, they moved with the grace and ferocity of the wilderness, their voice the creaking of trees and the sound of hoof against unspoiled earth. They might have been a dryad queen or a primeval beast, but it seemed all of nature was theirs to defend.',
    lessonName: 'Lesson of Wild Speech', initialHex: 'Wilding Word', initialFamiliarSpell: 'Summon Animal', initialFamiliarSpellAlt: 'Summon Plant or Fungus',
    familiarAbilityName: 'Familiar of Keen Senses', familiarAbilityDesc: "Whenever you Cast or Sustain a hex, your familiar gains your choice of an imprecise scent, tremorsense, or wavesense (range 60 feet) until the start of your next turn, and can immediately Point Out as a free action." },
];


