// Player Core classes (fully modeled).
export const CLASSES = [
  { key: 'fighter', name: 'Fighter', desc: 'Fighting for honor, greed, loyalty, or simply the thrill of battle, you are an undisputed master of weaponry and combat techniques. You combine your actions through clever combinations of opening moves, finishing strikes, and counterattacks whenever your foes are unwise enough to drop their guard. Whether you are a knight, mercenary, sharpshooter, or blade master, you have honed your martial skills into an art form and perform devastating critical attacks on your enemies.', book: 'player-core', hp: 10, keyAbility: ['str', 'dex'], skillChoice: ['acrobatics', 'athletics'],
    saves: { fort: 2, ref: 2, will: 1 }, perception: 2, classDC: 1,
    skillsTrainedCount: 3, weapons: 'Expert in simple and martial weapons; trained in advanced.', armor: 'Trained in all armor.',
    proficiencies: { perception: 'Expert', saves: { fort: 'Expert', ref: 'Expert', will: 'Trained' }, skills: ['Trained in your choice of Acrobatics or Athletics', 'Trained in a number of additional skills equal to 3 plus your Intelligence modifier'], attacks: ['Expert in simple weapons', 'Expert in martial weapons', 'Trained in advanced weapons', 'Expert in unarmed attacks'], defenses: ['Trained in all armor', 'Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: null,
    features: [
      { name: "Attack of Opportunity", action: 'R', desc: "Make a reaction Strike against an adjacent foe that uses a manipulate action, moves, or leaves a square during a move action." },
      { name: "Shield Block", action: 'R', desc: "Reduce damage from a hit by your shield’s Hardness using a reaction, at the cost of the shield’s Hit Points." },
      { name: "Bravery", level: 3, desc: "Your Will saving throw proficiency increases to expert. When you roll a success on a Will save against a fear effect, you get a critical success instead, and you gain the frightened 1 condition when you fail a Will save against a fear effect instead of frightened 2." },
    ],
    feats: [
      { name: 'Combat Assessment', level: 1, action: '1', desc: 'You make a telegraphed attack to learn about your foe. Make a melee Strike. On a hit, you can immediately attempt a check to Recall Knowledge about the target. On a critical hit, you gain a +2 circumstance bonus to the check to Recall Knowledge. The target is temporarily immune to Combat Assessment for 1 day.' },
      { name: 'Double Slice', level: 1, action: '2', desc: 'Requirements - You are wielding two melee weapons, each in a different hand\nYou lash out at your foe with both weapons. Make two Strikes, one with each of your two melee weapons, each using your current multiple attack penalty. Both Strikes must have the same target. If the second Strike is made with a weapon that doesn’t have the agile trait, it takes a –2 penalty.\nIf both attacks hit, combine their damage, and then add any other applicable effects from both weapons. You add any precision damage only once, to the attack of your choice. Combine the damage from both Strikes and apply resistances and weaknesses only once. This counts as two attacks when calculating your multiple attack penalty.' },
      { name: 'Exacting Strike', level: 1, action: '1', desc: 'You make a controlled follow-up attack, fully accounting for your momentum. Make a Strike. The Strike gains the following failure effect.\nFailure - This attack does not count toward your multiple attack penalty.' },
      { name: 'Point-Blank Stance', level: 1, action: '1', desc: 'Requirements - You are wielding a ranged weapon\nYou take aim to pick off nearby enemies quickly. When using a ranged volley weapon while you are in this stance, you don’t take the penalty to your attack rolls from the volley trait. When using a ranged weapon that doesn’t have the volley trait, you gain a +2 circumstance bonus to damage rolls on attacks against targets within the weapon’s first range increment.' },
      { name: 'Reactive Shield', level: 1, action: 'R', desc: 'Trigger - An enemy hits you with a melee Strike\nRequirements - You are wielding a shield\nYou can snap your shield into place just as you would take a blow, avoiding the hit at the last second. You immediately use the Raise a Shield action and gain your shield’s bonus to AC. The circumstance bonus from the shield applies to your AC when you’re determining the outcome of the triggering attack.' },
      { name: 'Snagging Strike', level: 1, action: '1', desc: 'Requirements - You have one hand free, and your target is within reach of that hand\nYou combine an attack with quick grappling moves to throw an enemy off balance as long as it stays in your reach. Make a Strike while keeping one hand free. If this Strike hits, the target is off-guard until the start of your next turn or until it’s no longer within the reach of your hand, whichever comes first.' },
      { name: 'Sudden Charge', level: 1, action: '2', desc: 'With a quick sprint, you dash up to your foe and swing. Stride twice. If you end your movement within melee reach of at least one enemy, you can make a melee Strike against that enemy. You can use Sudden Charge while Burrowing, Climbing, Flying, or Swimming instead of Striding if you have the corresponding movement type.' },
      { name: 'Vicious Swing', level: 1, action: '2', desc: 'You unleash a particularly powerful attack that clobbers your foe but leaves you a bit unsteady. Make a melee Strike. This counts as two attacks when calculating your multiple attack penalty. If this Strike hits, you deal an extra die of weapon damage. If you’re at least 10th level, increase this to two extra dice, and if you’re at least 18th level, increase it to three extra dice.' },
      { name: 'Aggressive Block', action: 'F', level: 2, desc: 'Trigger - You use the Shield Block reaction, and the opponent that triggered Shield Block is adjacent to you and is your size or smaller\nYou push back as you block, knocking your foe away or off balance. You use your shield to push the triggering creature, either automatically Shoving it 5 feet or causing it to become off-guard until the start of your next turn. The triggering creature chooses whether to be moved or become off-guard. If it chooses to be moved, you choose the direction. If the Shove would cause it to hit a solid object, enter a square of difficult terrain, or enter another creature’s space, it must become off-guard instead of being moved.' },
      { name: 'Assisting Shot', level: 2, action: '1', desc: 'Requirements - You are wielding a ranged weapon\nUsing your last shot to gauge your accuracy, you can fire off a quick shot to interfere with a foe in combat. Make a Strike with a ranged weapon. If the Strike hits, the next creature other than you to attack the same target before the start of your next turn gains a +1 circumstance bonus to their roll, or a +2 circumstance bonus if your Strike was a critical hit.' },
      { name: 'Blade Brake', level: 2, action: 'R', desc: 'Trigger - You would be moved by a forced movement effect\nRequirements - You are wielding a melee weapon and are within reach of a hard surface\nYou plow your weapon into a floor, wall, or another sturdy surface, anchoring yourself in place. If you would be moved 20 feet or more, you are moved only 5 feet. Otherwise, you don’t move at all.' },
      { name: 'Brutish Shove', level: 2, action: '1', desc: 'Requirements - You are wielding a two-handed melee weapon\nUsing the momentum of your last attack to throw your weight into another, you make your opponent stumble back. Make a Strike with a two-handed melee weapon. If you hit a target that is your size or smaller, that creature is off-guard until the end of your current turn, and you can automatically Shove it, with the same benefits as the Shove action (including the critical success effect, if your Strike was a critical hit). If you move to follow the target, your movement doesn’t trigger reactions. This Strike has the following failure effect.\nFailure - The target becomes off-guard until the end of your current turn.' },
      { name: 'Combat Grab', level: 2, action: '1', desc: 'Requirements - You have one hand free, and your target is within reach of that hand\nUsing your prior attack to shift your opponent’s guard, you take another swing and grab them. Make a melee Strike while keeping one hand free. If the Strike hits, you grab the target using your free hand. The creature remains grabbed until the end of your next turn or until it Escapes, whichever comes first.' },
      { name: 'Dueling Parry', level: 2, action: '1', desc: 'Requirements - You are wielding a single one-handed melee weapon and hold nothing else in your hands\nYou can parry attacks against you with your one-handed weapon. You gain a +2 circumstance bonus to AC until the start of your next turn as long as you continue to meet the requirements.' },
      { name: 'Intimidating Strike', level: 2, action: '2', desc: 'Your blow not only wounds creatures but also shatters their confidence. Make a melee Strike. If you hit and deal damage, the target is frightened 1, or frightened 2 on a critical hit.' },
      { name: 'Lightning Swap', level: 2, action: '1', desc: 'You have practiced quickly switching between combat styles and the equipment needed for them. You Interact to stow any number of items from your hands, then draw up to two weapons or a shield and a weapon.' },
      { name: 'Barreling Charge', level: 4, action: '2', reqSkills: [{ skill: 'athletics', rank: 1 }], desc: 'You rush forward, moving enemies aside to reach your foe. You Stride, attempting to move through your enemies’ spaces. Roll an Athletics check and compare the result to the Fortitude DC of each creature whose space you attempt to move through during your Stride, moving through its space on a success but ending your movement before entering its space on a failure. You can then Strike, regardless of how your Stride ended. You can use Barreling Charge to Burrow, Climb, Fly, or Swim instead of Stride if you have the corresponding movement type.' },
      { name: 'Double Shot', level: 4, action: '2', desc: 'Requirements - You are wielding a ranged weapon with reload 0\nYou shoot twice in blindingly fast succession. Make two Strikes, each against a separate target and with a –2 penalty. Both attacks count toward your multiple attack penalty, but the penalty doesn’t increase until after you’ve made both of them.' },
      { name: 'Dual-Handed Assault', level: 4, action: '1', desc: 'Requirements - You are wielding a one-handed melee weapon and have a free hand\nYou snap your free hand over to grip your weapon just long enough to add momentum and deliver a more powerful blow to your opponent. Make a Strike with the required weapon. You quickly switch your grip during the Strike in order to make the attack with two hands. If the weapon doesn’t normally have the two-hand trait, increase its weapon damage die by one step for this attack. (Rules on increasing die size appear on page 276.) If the weapon has the two-hand trait, you gain the benefit of that trait and a circumstance bonus to damage equal to the weapon’s number of damage dice. When the Strike is complete, you resume gripping the weapon with only one hand. This action doesn’t end any stance or fighter feat effect that requires you to have one hand free.' },
      { name: 'Parting Shot', level: 4, action: '2', desc: 'Requirements - You are wielding a loaded ranged weapon or a ranged weapon with reload 0\nYou jump back and make a quick shot that catches your opponent by surprise. You Step and then make a ranged Strike with the required weapon. Your target is off-guard against the attack.' },
      { name: 'Powerful Shove', level: 4, reqFeatsAny: ['Aggressive Block', 'Brutish Shove'], desc: 'You can push larger foes around with your attack. You can use Aggressive Block or Brutish Shove against a creature up to two sizes larger than you.\nWhen a creature you Shove or knock back with a shield, polearm, or club’s critical specialization effect has to stop moving because it would hit an object, it takes damage equal to your Strength modifier (minimum 1).' },
      { name: 'Quick Reversal', level: 4, action: '1', desc: 'Requirements - You are flanked by at least two enemies\nYou turn your foes’ flanking against them with a quick reverse. Make a melee Strike against one of the flanking enemies and make a second Strike with the same weapon or unarmed attack against a different enemy that is flanking you. This second Strike has the same multiple attack penalty of the initial attack and doesn’t count toward your multiple attack penalty.' },
      { name: 'Shielded Stride', level: 4, desc: 'When your shield is up, your enemies’ blows can’t touch you. When you have your shield raised, you can Stride to move half your Speed without triggering reactions that are triggered by your movement (such as Reactive Strikes). You can use Shielded Stride while Flying or Swimming instead of Striding if you have the corresponding movement type.' },
      { name: 'Slam Down', level: 4, action: '2', reqSkills: [{ skill: 'athletics', rank: 1 }], desc: 'You make an attack to knock a foe off balance, then follow up immediately with a sweep to topple them. Make a melee Strike. If it hits and deals damage, you can attempt an Athletics check to Trip the creature you hit. If you’re wielding a two-handed melee weapon, you can ignore Trip’s requirement that you have a hand free. Both attacks count toward your multiple attack penalty, but the penalty doesn’t increase until after you’ve made both of them.' },
      { name: 'Swipe', level: 4, action: '2', desc: 'You make a wide, arcing swing. Make a melee Strike and compare the attack roll result to the AC of up to two foes, each of whom must be within your melee reach and adjacent to each other. Roll damage only once and apply it to each creature you hit. A Swipe counts as two attacks for your multiple attack penalty.\nIf you’re using a weapon with the sweep trait, its modifier applies to all your Swipe attacks.' },
      { name: 'Twin Parry', level: 4, action: '1', desc: 'Requirements - You are wielding two melee weapons, one in each hand\nYou use your two weapons to parry attacks. You gain a +1 circumstance bonus to AC until the start of your next turn, or a +2 circumstance bonus if either weapon has the parry trait. You lose this circumstance bonus if you no longer meet this feat’s requirement.' },
      { name: 'Advanced Weapon Training', level: 6, desc: 'You’ve studied the art of wielding an advanced weapon. Choose a weapon group. You gain proficiency with all advanced weapons in that group as if they were martial weapons of their weapon group.' },
      { name: 'Advantageous Assault', level: 6, action: '1', desc: 'After compromising your enemy’s movement, you deliver a more deadly blow. Make a Strike against a creature that is grabbed, prone, or restrained. You gain a circumstance bonus to damage on this Strike equal to the number of weapon damage dice, or that number + 2 if you’re wielding the weapon in two hands. The Strike gains the following failure effect.\nFailure - You deal damage to the target equal to the number of weapon damage dice, or that number + 2 if you’re wielding the weapon in two hands. This damage has the same damage type as the weapon.' },
      { name: 'Dazing Blow', level: 6, action: '1', desc: 'Requirements - You have a creature grabbed\nYou pummel a held foe, hoping to stagger them. Make a melee Strike against a creature you have grabbed. The weapon damage from this Strike is bludgeoning damage. If the Strike hits, the creature must attempt a Fortitude save against your class DC; this is an incapacitation effect.\nCritical Success - The creature is unaffected.\nSuccess - The creature is stunned 1.\nFailure - The creature is stunned 2.\nCritical Failure - The creature is stunned 3.' },
      { name: 'Disarming Stance', level: 6, action: '1', reqSkills: [{ skill: 'athletics', rank: 1 }], desc: 'Requirements - You are wielding a single one-handed melee weapon and hold nothing else in your hands\nYou adopt a fencing stance that improves your control over your weapon. While you are in this stance, you gain a +1 circumstance bonus to Athletics checks to Disarm and a +2 circumstance bonus to your Reflex DC when defending against checks to Disarm you. In addition, you can attempt to Disarm creatures up to two sizes larger than you.' },
      { name: 'Furious Focus', level: 6, reqFeats: ['Vicious Swing'], desc: 'You’ve learned to maintain your balance even when swinging furiously. When you make a Vicious Swing with a melee weapon you’re wielding in two hands, it counts as one attack toward your multiple attack penalty instead of two.' },
      { name: 'Guardian’s Deflection', level: 6, action: 'R', desc: 'Trigger - An ally within your melee reach is hit by an attack, you can see the attacker, and the ally gaining a +2 circumstance bonus to AC would turn the critical hit into a hit or the hit into a miss\nRequirements - You are wielding a single one-handed melee weapon and hold nothing else in your hands.\nYou use your weapon to deflect the attack against your ally, granting a +2 circumstance bonus to their Armor Class against the triggering attack. This turns the triggering critical hit into a hit, or the triggering hit into a miss.' },
      { name: 'Reflexive Shield', level: 6, desc: 'You can use your shield to fend off explosions and the like. When you Raise your Shield, you gain your shield’s circumstance bonus to Reflex saves.\nSpecial - If you have the Shield Block reaction, damage you take as a result of a Reflex save can trigger that reaction, even if the damage isn’t physical damage.' },
      { name: 'Revealing Stab', level: 6, action: '2', desc: 'Requirements - You are wielding a melee weapon that can deal piercing damage\nYou drive your piercing weapon into an imperceptible foe, revealing its location to your allies. Make a Strike with a piercing melee weapon. If the target is concealed, you don’t need to attempt a flat check to target it, and if it’s hidden, the DC of the flat check to target it is 5. If you hit and deal damage, you can drive the weapon you attacked with into the target (if it’s corporeal), revealing its current position. You Release the weapon, and it becomes lodged in the target. If the target is concealed, no flat check is needed to target it, and if it’s hidden, the DC of the flat check to target it is 5, and the creature can’t become undetected. These benefits apply only for observers who can see your weapon stuck in the target. If the target is invisible, the weapon remains visible while lodged in it.\nThis benefit lasts until the weapon is removed from the creature. An adjacent creature or the target can remove the weapon with two Interact actions.' },
      { name: 'Ricochet Stance', level: 6, action: '1', desc: 'You adopt a stance to rebound your thrown weapons toward you. While you are in this stance, any thrown weapons you use as part of a ranged Strike to deal bludgeoning or slashing damage immediately return to your hand, enabling you to use them for additional Strikes. You must be within the weapon’s listed range increment and have a hand free to catch the weapon. If you make a ranged Strike with a thrown weapon outside of its listed range increment, it instead flies back toward you a number of feet equal to its listed range increment and then falls to the ground.' },
      { name: 'Shatter Defenses', level: 6, action: '1', desc: 'Requirements - A frightened creature is in your melee reach\nYour offense exploits your enemy’s fear. Make a melee Strike against a frightened creature. If you hit and deal damage, the target becomes off-guard until its frightened condition ends. If the target was already off-guard to you when you damaged it with this Strike, it can’t reduce its frightened value below 1 until the start of your next turn.' },
      { name: 'Shield Warden', level: 6, reqFeats: ['Shield Block'], desc: 'When you have a shield raised, you can use your Shield Block reaction when an attack is made against an ally adjacent to you. If you do, the shield prevents that ally from taking damage instead of preventing you from taking damage, following the normal rules for Shield Block.' },
      { name: 'Triple Shot', level: 6, reqFeats: ['Double Shot'], desc: 'You can quickly fire multiple shots with greater control. When you use Double Shot, you can make the attacks against the same target. You can add an additional action to Double Shot to make three ranged Strikes instead of two. If you do, the penalty is –4. All attacks count toward your multiple attack penalty, but the penalty doesn’t increase until after you’ve made all of them.' },
      { name: 'Blind-Fight', level: 8, reqPerception: 3, desc: 'Your battle instincts make you more aware of concealed and invisible opponents. You don’t need to succeed at a flat check to target concealed creatures. You’re not off-guard to creatures that are hidden from you (unless you’re off-guard to them for reasons other than the hidden condition), and you need only a successful DC 5 flat check to target a hidden creature.\nWhile you’re adjacent to an undetected creature of your level or lower, it is instead only hidden from you' },
      { name: 'Disorienting Opening', level: 8, desc: 'You use your foes’ openings to expose even greater weaknesses. When you hit a creature as part of a Reactive Strike, that creature becomes off-guard until the start of your next turn.' },
      { name: 'Dueling Riposte', level: 8, reqFeats: ['Dueling Parry'], action: 'R', desc: 'Trigger - A creature within your reach critically fails a Strike against you\nRequirements - You are benefiting from Dueling Parry\nYou elegantly counterattack against your flailing enemy. Make a melee Strike against or attempt to Disarm the triggering creature.' },
      { name: 'Felling Strike', level: 8, action: '2', desc: 'Your attack can ground an airborne foe. Make a Strike. If it hits and deals damage to a flying target, the target falls up to 120 feet. The fall is gradual enough that if it causes the target to hit the ground, the target takes no damage from the fall.\nIf the attack is a critical hit, the target can’t Fly, Leap, levitate, or otherwise leave the ground until the end of your next turn.' },
      { name: 'Incredible Aim', level: 8, action: '2', desc: 'By spending a moment to focus, you can ensure your attack strikes true. Make a ranged weapon Strike. On this Strike, you gain a +2 circumstance bonus to the attack roll and ignore the target’s concealed condition.' },
      { name: 'Mobile Shot Stance', level: 8, action: '1', desc: 'Your shots become nimble and deadly. While you’re in this stance, your ranged Strikes don’t trigger Reactive Strike or other reactions that are triggered by a ranged attack.\nSpecial - If you have Reactive Strike, you can use it with a loaded ranged weapon you’re wielding. The triggering creature must be within 5 feet of you for you to do so.' },
      { name: 'Positioning Assault', level: 8, action: '2', desc: 'Requirements - You are wielding a two-handed melee weapon and your target is within your reach\nWith punishing blows, you force your opponent into position. Make a Strike with the required weapon. If you hit, you Reposition the target 5 feet.' },
      { name: 'Quick Shield Block', level: 8, reqFeats: ['Shield Block'], desc: 'You can bring your shield into place with hardly a thought. At the start of each of your turns, you gain an additional reaction that you can use only to Shield Block.' },
      { name: 'Resounding Bravery', level: 8, desc: 'Even your fears serve as fuel for your fighting spirit. When you critically succeed at a Will save against a foe’s ability, you gain a +1 status bonus to saves and a number of temporary Hit Points equal to half your level for 1 minute. These benefits are doubled if you critically succeed against a fear effect.' },
      { name: 'Sudden Leap', level: 8, action: '2', desc: 'You make an impressive leap and swing while you soar. Make a Leap, High Jump, or Long Jump and attempt one melee Strike at any point during your jump. Immediately after the Strike, you fall to the ground if you’re in the air, even if you haven’t reached the maximum distance of your jump. If the distance you fall is no more than the height of your jump, you take no damage and land upright.\nWhen attempting a High Jump or Long Jump during a Sudden Leap, determine the jump distance using Long Jump’s rules, and change your maximum distance to double your Speed.\nSpecial - If you have Felling Strike, you can use Felling Strike instead of a normal Strike. This doesn’t change the number of actions Sudden Leap takes.' },
    ] },
  { key: 'rogue', name: 'Rogue', desc: 'You are skilled and opportunistic. Using your sharp wits and quick reactions, you take advantage of your opponents’ missteps and strike where it hurts most. You play a dangerous game, seeking thrills and testing your skills, and likely don’t care much for any laws that happen to get in your way. While the path of every rogue is unique and riddled with danger, the one thing you all share in common is the breadth and depth of your skills.', book: 'player-core', hp: 8, keyAbility: ['dex'],
    saves: { fort: 1, ref: 2, will: 2 }, perception: 2, classDC: 1,
    skillsTrainedCount: 7, weapons: 'Trained in simple and martial weapons.', armor: 'Trained in light armor.',
    proficiencies: { perception: 'Expert', saves: { fort: 'Trained', ref: 'Expert', will: 'Expert' }, skills: ['Trained in Stealth', 'Trained in one or more skills determined by your rogue’s racket', 'Trained in a number of additional skills equal to 7 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in martial weapons', 'Trained in unarmed attacks'], defenses: ['Trained in light armor', 'Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: null,
    fixedSkills: ['stealth'],
    subclassLabel: 'Racket',
    subclasses: [
      { key: 'mastermind', name: 'Mastermind', desc: 'Rely on intellect to craft intricate schemes. Trained in Society and a choice of Arcana, Nature, Occultism, or Religion.', grantedSkills: ['society'], skillChoice: ['arcana', 'nature', 'occultism', 'religion'] },
      { key: 'ruffian', name: 'Ruffian', desc: 'Prefer the direct approach of strong-arming or intimidation. Trained in Intimidation and medium armor.', grantedSkills: ['intimidation'] },
      { key: 'scoundrel', name: 'Scoundrel', desc: 'Use fast-talking, flattery, and a silver tongue. Trained in Deception and Diplomacy.', grantedSkills: ['deception', 'diplomacy'] },
      { key: 'thief', name: 'Thief', desc: 'Nothing beats the thrill of taking something that belongs to someone else. You might be a pickpocket working the streets, a cat burglar sneaking through windows, or even a consultant, testing your clients’ vaults for openings.  When a fight breaks out, you prefer swift, lightweight weapons, and you strike where it hurts. When you attack with a finesse melee weapon or finesse melee unarmed attack, you can add your Dexterity modifier to damage rolls instead of your Strength modifier.  You are trained in Thievery.', grantedSkills: ['thievery'] },
    ],
    features: [
      { name: "Sneak Attack (1d6)", desc: "Deal extra precision damage when Striking a flat-footed creature." },
      { name: "Surprise Attack", desc: "Creatures that haven’t acted are flat-footed to you on the first round of combat." },
      { name: "Deny Advantage", level: 3, desc: "You're not flat-footed to creatures of a lower level than you, even from conditions or effects that would normally flat-foot you against them (such as being flanked). You can still be flat-footed to such a creature's spells and other abilities that don't key off its level." },
    ],
    feats: [
      { name: 'Nimble Dodge', level: 1, action: 'R', desc: 'Trigger - A creature targets you with an attack and you can see the attacker\nRequirements - You are not encumbered\nYou deftly dodge out of the way, gaining a +2 circumstance bonus to AC against the triggering attack.' },
      { name: 'Overextending Feint', level: 1, reqSkills: [{ skill: 'deception', rank: 1 }], desc: 'You goad a foe into overextending. On a successful Feint, you can use the following success and critical success effects instead of any other effects that would occur when you Feint.\nCritical Success - The target takes a –2 circumstance penalty to all attack rolls against you before the end of its next turn.\nSuccess - The target takes a –2 circumstance penalty to its next attack roll against you before the end of its next turn.' },
      { name: 'Plant Evidence', level: 1, action: '1', reqFeats: ['Pickpocket'], desc: 'You can put a single item you’re holding of light or negligible Bulk onto a person without them noticing by succeeding at a Thievery check against their Perception DC. If you have the ruffian racket, you can do this as a free action when you successfully Shove a target.' },
      { name: 'Trap Finder', level: 1, desc: 'You have an intuitive sense that alerts you to the presence of traps. You gain a +1 circumstance bonus to Perception checks to find traps, to AC against attacks made by traps, and to saves against traps. Even if you aren’t Searching, you get a check to find traps that normally require you to be Searching. You still need to meet any other requirements to find the trap.\nYou can disable traps that require a proficiency rank of master in Thievery. If you have master proficiency in Thievery, you can disable traps that require a proficiency rank of legendary instead, and your circumstance bonuses against traps increase to +2.' },
      { name: 'Twin Feint', level: 1, action: '2', desc: 'Requirements - You are wielding two melee weapons, each in a different hand\nYou use an attack with one weapon to distract your foe from a second attack coming at a different angle. Make one Strike with each of your two melee weapons, both against the same target. The target is automatically off-guard against the second attack. Apply your multiple attack penalty to the Strikes normally.' },
      { name: "You're Next", level: 1, reqSkills: [{ skill: 'intimidation', rank: 1 }], desc: 'Trigger - You reduce an enemy to 0 Hit Points\nAfter downing a foe, you menace another. Attempt to Demoralize a creature within 60 feet, with a +2 circumstance bonus. If you have legendary proficiency in Intimidation, you can use this as a free action with the same trigger.' },
      { name: 'Underhanded Assault', level: 2, action: '2', reqSkills: [{ skill: 'stealth', rank: 1 }], desc: 'You capitalize on the distraction provided by an ally. You Sneak up to a foe adjacent to one of your allies. You can roll against the foe you’re Sneaking up on, even if it’s currently observing you, as though you were hidden. You take a –2 penalty on your Stealth check. If your Stealth check against the chosen foe succeeds, you can make a melee Strike against that foe at the end of your Sneak.' },
      { name: 'Brutal Beating', level: 2, reqSubclass: 'ruffian', desc: 'Your critical hits shakes your foes’ confidence. Whenever your Strike is a critical hit and deals damage, the target is frightened 1.' },
      { name: 'Clever Gambit', level: 2, reqSubclass: 'mastermind', action: 'R', desc: 'Trigger - Your Strike critically hits and deals damage to a creature you’ve identified with Recall Knowledge\nYour battle tactics are aided by assessing your foe’s capabilities and range. You Step or Stride; this movement doesn’t trigger reactions from the triggering creature.' },
      { name: 'Distracting Feint', level: 2, reqSubclass: 'scoundrel', desc: 'Your Feints are far more distracting than normal. While a creature is off-guard by your Feint, it also takes a –2 circumstance penalty to Perception checks and Reflex saves.' },
      { name: 'Mobility', level: 2, desc: 'You move without leaving an opening. When you Stride and move half your Speed or less, that movement does not trigger reactions. You can use Mobility when Climbing, Flying, or Swimming instead of Striding if you have the corresponding movement type.' },
      { name: 'Quick Draw', level: 2, action: '1', desc: 'You draw your weapon and attack with the same motion. You Interact to draw a weapon, then Strike with that weapon.' },
      { name: 'Strong Arm', level: 2, desc: 'When you Strike with a thrown weapon, the weapon’s range increment increases by 10 feet.' },
      { name: 'Unbalancing Blow', level: 2, reqSubclass: 'thief', desc: 'Interweaving attacks, you unbalance your foes. Whenever your Strike is a critical hit and deals damage, the target is offguard against your attacks until the end of your next turn.' },
      { name: 'Dread Striker', level: 4, desc: 'You capitalize on your enemies’ fear to slip past their defenses. Any creature that has the frightened condition is also off-guard against your attacks.' },
      { name: 'Head Stomp', level: 4, action: '1', desc: 'Make an unarmed melee Strike against a prone target. If it hits, until the end of your next turn the target is stupefied 1 (or stupefied 2 on a critical hit) and off-guard.' },
      { name: 'Mug', level: 4, action: '2', desc: 'You make a quick attack and rob your foe in the process. Make a melee Strike against an adjacent enemy. If you hit and deal sneak attack damage, you can also attempt to Steal from the target, even if the target is in combat.' },
      { name: 'Poison Weapon', level: 4, action: '1', desc: 'Requirements - You are wielding a weapon.\nYou apply a contact poison or injury poison to the required weapon; if you have a free hand, you can Interact to draw a poison as part of this action. This poison can be one of the simple injury poisons you can create due to this feat (see Special), or another contact or injury poison you’ve acquired (such as those in GM Core).\nSpecial - During your daily preparations, you can prepare a number of simple injury poisons equal to your level. These follow the rules for injury poisons (GM Core, page 248), except that they deal 1d4 poison damage with no saving throw. Only you can apply these poisons properly, and they expire the next time you prepare.' },
      { name: 'Predictable!', level: 4, action: '1', desc: 'By observing an opponent, you can get a sense of their next move and prepare to counter or resist it. Choose one target and attempt a Perception check to Sense Motive against the foe’s Deception DC or a hard DC of the foe’s level, whichever is higher.\nCritical Success - You precisely discern the target’s strategy, gaining a +2 circumstance bonus to AC against the creature until the start of your next turn and a +2 circumstance bonus to your next saving throw against the creature before the start of your next turn.\nSuccess - You deduce the gist of the target’s strategy; as critical success, except the circumstance bonus is only +1.\nFailure - You fail to discern the target’s strategy and gain no benefit.\nCritical Failure - You misinterpret the target’s strategy and take a –1 circumstance penalty to AC against the creature until the start of your next turn, and a –1 circumstance penalty to your next saving throw against the creature before the start of your next turn.' },
      { name: 'Reactive Pursuit', level: 4, action: 'R', desc: 'Trigger - An adjacent foe moves away from you, and you can reach at least one space adjacent to the foe with a Stride action\nYou keep pace with a retreating foe. You Stride, but you must end your movement adjacent to the triggering enemy. Your move does not trigger reactions from the triggering enemy. You can use Reactive Pursuit to Burrow, Climb, Fly, or Swim instead of Stride if you have the corresponding movement type.' },
      { name: 'Sabotage', level: 4, action: '1', desc: 'Requirements - You have a free hand\nYou subtly damage others’ equipment. Choose one item that a creature within your reach wields or carries. The item must have moving parts that you could possibly sabotage (a shortbow could be sabotaged, but a longsword could not). Attempt a Thievery check against the Reflex DC of the creature. Damage dealt by Sabotage can’t take the item below its Broken Threshold.\nCritical Success - You deal damage equal to four times your Thievery proficiency bonus.\nSuccess - You deal damage equal to double your Thievery proficiency bonus.\nCritical Failure - Temporarily immune to your Sabotage for 1 day.' },
      { name: 'Scoundrel’s Surprise', level: 4, action: '1', desc: 'You drop your disguise at the right moment and surprise your target. After you Impersonate someone else using a disguise kit, you can remove your disguise with a dramatic gesture. Any creatures that previously failed to see through your disguise are off-guard against the next attack you make before the end of your turn.' },
      { name: 'Scout’s Warning', action: 'F', level: 4, desc: 'Trigger - You are about to roll a Perception or Survival check for initiative\nYou visually or audibly warn your allies of danger, granting them each a +1 circumstance bonus to their initiative rolls, or a +2 circumstance bonus if you’re using the Scout exploration activity. Depending on whether you use gestures or call out, this action gains either the visual or the auditory trait, respectively.' },
      { name: 'The Harder They Fall', level: 4, desc: 'You make your foes fall painfully when you trip them. When you successfully Trip an off-guard foe, your target takes 1d6 bludgeoning damage. On a critical success, the target takes 1d6 bludgeoning damage plus your sneak attack damage.' },
      { name: 'Twin Distraction', level: 4, reqFeats: ['Twin Feint'], desc: 'Requirements - You are wielding two melee weapons, each in a different hand\nYour movements with two weapons are so swift and disorienting that they befuddle your opponent. When using Twin Feint, if both your Strikes deal damage to a targeted creature, the target must succeed at a Will saving throw against your class DC or become stupefied 1 until the end of your next turn.' },
      { name: 'Analyze Weakness', level: 6, action: '1', desc: 'Requirements - You have identified a creature with Recall Knowledge\nYour knowledge of a creature’s physiology helps you attack with pinpoint accuracy. You carefully study a creature that you’ve identified to scope out particularly weak points in its positioning or physical form. The next time you deal sneak attack damage to the chosen creature with a Strike before the end of your turn, add an additional 2d6 precision damage.\nAt 11th level, the additional damage becomes 3d6, and at 17th level it becomes 4d6.' },
      { name: 'Anticipate Ambush', level: 6, reqSkills: [{ skill: 'stealth', rank: 2 }], desc: 'You keep watch for any hidden creatures or dangerous sites, moving at half your travel Speed. If you’re Anticipating an Ambush at the start of an encounter, you roll a Perception check for initiative, and all enemies rolling Stealth for initiative take a –2 circumstance penalty to their Stealth checks.' },
      { name: 'Far Throw', level: 6, desc: 'When you Strike with a thrown weapon, you take only a –1 penalty for each additional range increment between you and the target, rather than a –2 penalty.' },
      { name: 'Gang Up', level: 6, desc: 'You and your allies harry an opponent in concert. You can flank an enemy if it’s within reach of both of you and an ally—you and your ally don’t have to be on opposite sides. This benefits your allies as well as you, but only if they’re flanking with you, not each other. The other requirements for flanking must still be met.' },
      { name: 'Light Step', level: 6, desc: 'You aren’t bothered by tricky footing. When you Stride or Step, you can ignore difficult terrain.' },
      { name: 'Shove Down', action: 'F', level: 6, reqSkills: [{ skill: 'athletics', rank: 1 }], desc: 'Requirements - Your last action was a successful Shove\nYou leverage your weight to topple foes that you move. You attempt to Trip the target, even if the target is no longer in your reach.' },
      { name: 'Skirmish Strike', level: 6, action: '1', desc: 'Your feet and weapon move in tandem. Either Step and then Strike, or Strike and then Step.' },
      { name: 'Sly Disarm', level: 6, desc: 'You can Disarm a creature through sleight of hand rather than brute force. You can use Thievery instead of Athletics when you attempt a Disarm. When you use Thievery to attempt a Disarm and succeed, the target is off-guard against the next attack you make before the end of your turn.' },
      { name: 'Twist the Knife', level: 6, action: '1', desc: 'Requirements - Your last action was a melee Strike that dealt sneak attack damage to an off-guard target\nAfter stabbing your opponent in a weak spot, you tear the wound open. You deal persistent bleed damage to the target equal to your number of sneak attack damage dice.' },
      { name: 'Watch Your Back', level: 6, action: '1', reqSkills: [{ skill: 'intimidation', rank: 1 }], desc: 'You menace the target, stoking their fears and drawing their attention. Attempt an Intimidation check against the Will DC of a target within 30 feet. If you succeed, for 1 minute, that target gains a +2 status bonus to Perception checks against you, but it takes a –2 status penalty to Will saves against fear effects.' },
      { name: 'Blind-Fight', level: 8, reqPerception: 3, desc: 'Your battle instincts make you more aware of concealed and invisible opponents. You don’t need to succeed at a flat check to target concealed creatures. You’re not off-guard to creatures that are hidden from you (unless you’re off-guard to them for reasons other than the hidden condition), and you need only a successful DC 5 flat check to target a hidden creature.\nWhile you’re adjacent to an undetected creature of your level or lower, it is instead only hidden from you' },
      { name: 'Bullseye', level: 8, action: '1', desc: 'You carefully take aim to avoid your foe’s concealment and cover. On your next Strike with a thrown weapon before the end of your turn, you gain a +1 circumstance bonus to your attack roll and ignore your target’s concealed condition, as well as the target’s lesser cover or standard cover; if the target had greater cover, they instead have only standard cover against the Strike.' },
      { name: 'Delay Trap', level: 8, action: 'R', desc: 'Trigger - A trap within your reach is triggered\nYou try to jam the workings of a trap to delay its effects. Attempt a Thievery check to Disable a Device on the trap with the following results instead of the normal ones for the action.\nCritical Success - You either prevent the trap from being triggered or delay the activation until the start or end of your next turn.\nSuccess - As above, but the GM chooses whichever is worse for you.\nFailure - No effect.\nCritical Failure - You’re off-guard until the start of your next turn.' },
      { name: 'Improved Poison Weapon', level: 8, reqFeats: ['Poison Weapon'], desc: 'You deliver poisons in ways that maximize their harmful effects. When you apply a simple poison with Poison Weapon, the poison deals 2d4 poison damage instead of 1d4 poison damage. You don’t waste a poison you apply with Poison Weapon on a critically failed attack roll.' },
      { name: 'Inspired Stratagem', level: 8, desc: 'During your daily preparations, you can review stratagems for the day’s adventures with up to five allies. Later, you can quickly advise them on your schemes using the below reaction.\nInspired Stratagem - Reaction (fortune, linguistic)\nTrigger - An ally you reviewed stratagems with is about to attempt an attack roll or skill check;\nEffect - The ally rolls the triggering check twice and takes the better of the two results. That ally then becomes temporarily immune to your Inspired Stratagem until your next daily preparations.' },
      { name: 'Nimble Roll', level: 8, reqFeats: ['Nimble Dodge'], desc: 'You throw yourself into a roll to escape imminent danger. You can use Nimble Dodge before attempting a Reflex save in addition to its original trigger. If you do, the circumstance bonus applies to your Reflex save against the triggering effect.\nWhen you use Nimble Dodge and the triggering attack fails or critically fails, or when you succeed or critically succeed at the saving throw, you can also Stride up to 10 feet as part of the reaction. If you do, the reaction gains the move trait. You can use Nimble Roll while Flying or Swimming instead of Striding if you have the corresponding movement type.' },
    ] },
  { key: 'wizard', name: 'Wizard', desc: 'You are an eternal student of the secrets of the universe, using your mastery of magic to cast powerful spells. You treat magic like a science, cross-referencing the latest texts on practical spellcraft with ancient tomes to discover and understand arcane magic. Yet magical theory is vast, and there’s no way you can study it all. Most wizards learn through formal schooling, with their curriculum informing a specific rubric, although particularly driven researchers sometimes piece together their own theories.', book: 'player-core', hp: 6, keyAbility: ['int'], noLevel1SkillFeat: true, noLevel1ClassFeat: true,
    saves: { fort: 1, ref: 1, will: 2 }, perception: 1, classDC: 1,
    skillsTrainedCount: 2, weapons: 'Trained in simple weapons.', armor: 'Trained in unarmored defense.',
    proficiencies: { perception: 'Trained', saves: { fort: 'Trained', ref: 'Trained', will: 'Expert' }, skills: ['Trained in Arcana', 'Trained in a number of additional skills equal to 2 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in unarmed attacks'], defenses: ['Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: { tradition: 'Arcane', keyAbility: 'int', type: 'prepared' },
    subclassLabel: 'Arcane School',
    // Curriculum maps spell rank (0 = cantrip) to that school's named curriculum options (Player Core,
    // ArcaneSchools.aspx). Unified Magical Theory forgoes a curriculum for a bonus feat + font benefit instead.
    subclasses: [
      { key: 'ars-grammatica', name: 'School of Ars Grammatica', desc: 'Study the fundamental forces of magic through runes, wards, and the power of language itself.', schoolSpell: 'Protective Wards', advancedSchoolSpell: 'Rune of Observation', curriculum: { 0: ['Message', 'Sigil'], 1: ['Command', 'Disguise Magic', 'Runic Body', 'Runic Weapon'], 2: ['Dispel Magic', 'Translate'], 3: ['Enthrall', 'Veil of Privacy'], 4: ['Dispelling Globe', 'Suggestion'], 5: ['Sending', 'Truespeech'], 6: ['Repulsion', 'Spellwrack'], 7: ['Contingency', 'Planar Seal'], 8: ['Quandary', 'Unrelenting Observation'], 9: ['Detonate Magic'] } },
      { key: 'battle-magic', name: 'School of Battle Magic', desc: 'Magic is power, and there are always those who will use power for the art of battle. You may have studied in the military of a nation of the brink of war—Cheliax and Andoran perhaps, or Geb and Nex. You summon whirling energies that can lay waste to both soldiers and armies, while being sure not to neglect arcane countermeasures for common tactical complications or the shields and defenses that keep combatants alive on the battlefield.', schoolSpell: 'Force Bolt', advancedSchoolSpell: 'Energy Absorption', curriculum: { 0: ['Shield', 'Telekinetic Projectile'], 1: ['Breathe Fire', 'Force Barrage', 'Mystic Armor'], 2: ['Mist', 'Resist Energy'], 3: ['Earthbind', 'Fireball'], 4: ['Wall of Fire', 'Weapon Storm'], 5: ['Howling Blizzard', 'Impaling Spike'], 6: ['Chain Lightning', 'Disintegrate'], 7: ['Energy Aegis', 'True Target'], 8: ['Arctic Rift', 'Desiccate'], 9: ['Falling Stars'] } },
      { key: 'boundary', name: 'School of the Boundary', desc: 'Turn your magic to the forces beyond, summoning spirits and manipulating dimensions and planes.', schoolSpell: 'Fortify Summoning', advancedSchoolSpell: 'Spiral of Horrors', curriculum: { 0: ['Telekinetic Hand', 'Void Warp'], 1: ['Grim Tendrils', 'Phantasmal Minion', 'Summon Undead'], 2: ['Darkness', 'See the Unseen'], 3: ['Bind Undead', 'Ghostly Weapon'], 4: ['Flicker', 'Translocate'], 5: ['Banishment', 'Invoke Spirits'], 6: ['Teleport', 'Vampiric Exsanguination'], 7: ['Eclipse Burst', 'Interplanar Teleport'], 8: ['Quandary', 'Unrelenting Observation'], 9: ['Massacre'] } },
      { key: 'civic-wizardry', name: 'School of Civic Wizardry', desc: 'Apply arcane study to practical civic needs: construction, transportation, and public works.', schoolSpell: 'Earthworks', advancedSchoolSpell: 'Community Restoration', curriculum: { 0: ['Prestidigitation', 'Read Aura'], 1: ['Hydraulic Push', 'Pummeling Rubble', 'Summon Construct'], 2: ['Revealing Light', 'Water Walk'], 3: ['Cozy Cabin', 'Safe Passage'], 4: ['Creation', 'Unfettered Movement'], 5: ['Control Water', 'Wall of Stone'], 6: ['Disintegrate', 'Wall of Force'], 7: ['Planar Palace', 'Retrocognition'], 8: ['Earthquake', 'Pinpoint'], 9: ['Foresight'] } },
      { key: 'mentalism', name: 'School of Mentalism', desc: 'Master the arts of illusion and mental manipulation, befuddling and beguiling lesser minds.', schoolSpell: 'Charming Push', advancedSchoolSpell: 'Invisibility Cloak', curriculum: { 0: ['Daze', 'Figment'], 1: ['Dizzying Colors', 'Sleep', 'Sure Strike'], 2: ['Illusory Creature', 'Stupefy'], 3: ['Dream Message', 'Mind Reading'], 4: ['Nightmare', 'Vision of Death'], 5: ['Hallucination', 'Illusory Scene'], 6: ['Never Mind', 'Phantasmal Calamity'], 7: ['Project Image', 'Warp Mind'], 8: ['Disappearance', 'Uncontrollable Dance'], 9: ['Phantasmagoria'] } },
      { key: 'protean-form', name: 'School of Protean Form', desc: 'Focus on the relationship between mind and body, transforming living matter into other shapes for a time.', schoolSpell: 'Scramble Body', advancedSchoolSpell: 'Shifting Form', curriculum: { 0: ['Gouging Claw', 'Tangle Vine'], 1: ['Jump', 'Pest Form', 'Spider Sting'], 2: ['Enlarge', 'Humanoid Form'], 3: ['Feet to Fins', 'Vampiric Feast'], 4: ['Mountain Resilience', 'Vapor Form'], 5: ['Elemental Form', 'Toxic Cloud'], 6: ['Cursed Metamorphosis', 'Petrify'], 7: ['Duplicate Foe', 'Fiery Body'], 8: ['Desiccate', 'Monstrosity Form'], 9: ['Metamorphosis'] } },
      { key: 'unified-magical-theory', name: 'School of Unified Magical Theory', desc: 'Reject a narrow curriculum in favor of broad versatility: gain an extra 1st-level feat and spell instead of school spells.', schoolSpell: 'Hand of the Apprentice', advancedSchoolSpell: 'Interdisciplinary Incantation', grantsFeat: { pool: 'class', maxLevel: 1 } },
    ],
    // Arcane Thesis (Player Core, ArcaneThesis.aspx) is a second, independent 1st-level choice
    // alongside Arcane School — kept as its own field rather than reusing the subclass mechanism.
    arcaneThesis: [
      { key: 'experimental-spellshaping', name: 'Experimental Spellshaping', desc: 'Gain one 1st-level wizard feat of your choice, reflecting efficient access to spellshape effects.', grantsFeat: { pool: 'class', maxLevel: 1 } },
      { key: 'improved-familiar-attunement', name: 'Improved Familiar Attunement', desc: 'Gain the Familiar feat for free. Your familiar gains an extra ability, and another at 6th, 12th, and 18th level.', grantsFeat: { pool: 'fixed', options: ['Familiar'] } },
      { key: 'spell-blending', name: 'Spell Blending', desc: 'During daily preparations, trade two spell slots of the same rank for one slot up to 2 ranks higher, or trade a slot for two extra cantrips.' },
      { key: 'spell-substitution', name: 'Spell Substitution', desc: 'Spend 10 minutes to swap a prepared spell slot for a different spell from your spellbook.' },
      { key: 'staff-nexus', name: 'Staff Nexus', desc: 'You begin the game with a custom makeshift staff that contains one cantrip and one 1st-rank spell from your spellbook. During daily preparations, you can expend a spell to charge the staff with temporary magical energy or merge it with another staff you own. Holding the staff allows you to cast its stored spells, with the 1st-rank spell consuming charges while the cantrip remains free to use. As you reach 8th and 16th levels, you gain the ability to expend up to two and three spells respectively to add significantly more charges.' },
    ],
    features: [{ name: "Arcane School", desc: "Study a school of arcane magic, gaining a school spell and other benefits." }, { name: "Arcane Thesis", desc: "A special benefit depending on the topic of your unique magical research." }, { name: "Arcane Bond", action: 'F', actionName: 'Drain Bonded Item', desc: "Recast a spell you’ve already prepared and cast today, without spending a spell slot. Once per day." }, { name: "Spellbook", desc: "Record the spells you know in a spellbook you can prepare from." }],
    feats: [
      { name: 'Counterspell', level: 1, action: 'R', desc: 'Trigger - A creature Casts a Spell that you have prepared\nWhen a foe Casts a Spell and you can see its manifestations, you can use your magic to disrupt it. You expend a prepared spell to counter the triggering creature’s casting of that same spell. You lose your spell slot as if you had cast the triggering spell. You then attempt to counteract the triggering spell.\nSpecial - This feat has the trait corresponding to the tradition of spells you cast (arcane, divine, primal, or occult).' },
      { name: 'Familiar', level: 1, desc: 'You make a pact with a creature that serves you and assists your spellcasting. You gain a familiar.' },
      { name: 'Reach Spell', action: '1', level: 1, desc: 'You can extend your spells’ range. If the next action you use is to Cast a Spell that has a range, increase that spell’s range by 30 feet. As is standard for increasing spell ranges, if the spell normally has a range of touch, you extend its range to 30 feet.' },
      { name: 'Spellbook Prodigy', level: 1, reqSkills: [{ skill: 'arcana', rank: 1 }], desc: 'You are particularly adept at learning spells to add to your spellbook. You gain the Magical Shorthand skill feat without needing to meet its prerequisites. Further, when you roll a critical failure on your check to Learn a Spell, you get a failure instead.' },
      { name: 'Widen Spell', action: '1', level: 1, desc: 'You manipulate the energy of your spell, causing it to spread out and affect a wider area. If the next action you use is to Cast a Spell that has an area of a burst, cone, or line and does not have a duration, increase the area of that spell. Add 5 feet to the radius of a burst that normally has a radius of at least 10 feet (a burst with a smaller radius is not affected). Add 5 feet to the length of a cone or line that is normally 15 feet long or smaller, and add 10 feet to the length of a larger cone or line.' },
      { name: 'Cantrip Expansion', level: 2, desc: 'Study broadens your range of simple spells.\nPrepared Caster (Cleric, Wizard, etc.) - You can prepare two additional cantrips each day.\nSpontaneous Caster (Bard, Sorcerer, etc.) - Add two additional cantrips from your spell list to your repertoire.' },
      { name: 'Conceal Spell', action: '1', level: 2, desc: 'Through sheer mental effort, you can simplify the incantations and gestures needed to spellcast, leaving them barely noticeable. If the next action you use is to Cast a Spell, the spell gains the subtle trait, hiding the shining runes, sparks of magic, and other manifestations that would usually give away your spellcasting. The trait hides only the spell’s spellcasting actions and manifestations, not its effects, so an observer might still see a ray streak out from you or see you vanish into thin air.' },
      { name: 'Energy Ablation', action: '1', level: 2, desc: 'As you direct destructive energy at a foe, you can divert some of its power into a protective barrier that shields you from harm. If your next action is to Cast a Spell that deals at least one type of energy damage (acid, cold, electricity, fire, force, sonic, vitality, or void), you gain resistance to an energy damage type of your choice equal to the spell’s rank. The resistance lasts until the end of your next turn. You get the resistance regardless of whether or not your spell dealt damage.' },
      { name: 'Enhanced Familiar', level: 2, desc: 'You infuse your familiar with additional primal energy, increasing its abilities. You can select four familiar or master abilities each day, instead of two.\nSpecial - [Witch] Add the bonus familiar abilities you gain for being a witch to this amount. [Wizard] If your arcane thesis is improved familiar attunement, your familiar’s base number of familiar abilities, before adding any extra abilities from the arcane thesis, is four.' },
      { name: 'Nonlethal Spell', action: '1', level: 2, desc: 'You can alter offensive spells to be less deadly. If your next action is to Cast a Spell that deals damage and doesn’t have the death or void trait, that spell gains the nonlethal trait.' },
      { name: 'Bespell Strikes', action: 'F', level: 4, desc: 'Frequency - once per turn\nRequirements - Your most recent action was to cast a non-cantrip spell\nYou siphon spell energy into one weapon you’re wielding, or into one of your unarmed attacks, such as a fist. Until the end of your turn, the weapon or unarmed attack deals an extra 1d6 force damage and gains the associated trait (see below) if it didn’t have it already. If the spell dealt a different type of damage, the Strike deals this type of damage instead (or one type of your choice if the spell could deal multiple types of damage).\nOracle - Your strike gains the divine trait.\nSorcerer: - Your strike gains the trait of your bloodline’s magical tradition.\nWizard - Your strike gains the arcane trait.' },
      { name: 'Call Wizardly Tools', action: '1', level: 4, desc: 'You’re mystically connected to your wizardly tools, ensuring you can always find them when you’ve misplaced them. You teleport your bonded item or spellbook to you. It arrives in your hand if you have a free hand or at your feet if you don’t. The item must be within 1 mile and have 1 Bulk or less.' },
      { name: 'Linked Focus', level: 4, desc: 'You have linked your bonded item to the well of energy that powers your school spells. Once per day when you Drain your Bonded Item to cast one of your arcane school’s curriculum spells, you also regain 1 Focus Point.' },
      { name: 'Spell Protection Array', level: 4, action: '1', desc: 'You inscribe a circle of arcane runes that dampen enemies’ magic. You create a glowing magic circle in a 5-foot burst within 30 feet. Creatures in the circle gain a +1 status bonus to saving throws against magic. The circle lasts until the end of your next turn, and you can Sustain it, to a maximum duration of 1 minute.' },
      { name: 'Convincing Illusion', level: 6, reqSkills: [{ skill: 'deception', rank: 2 }], action: 'R', desc: 'Trigger - A creature succeeded, but didn’t critically succeed, at a Perception check or Will save to disbelieve an illusion from a spell that you cast\nRequirements - You are within 30 feet of the observer and the illusion\nYou use your deceptive skills to make your illusions seem even more real. Attempt a Deception check against the target’s Perception DC. If you succeed, the target fails to disbelieve the illusion.' },
      { name: 'Explosive Arrival', action: 'F', level: 6, desc: 'Your summoned creature appears in a detonation of arcane runes. If your next action is to Cast a Spell with the summon trait, all creatures in a 10-foot emanation around the creature you summoned take 1d4 fire damage per spell rank. If the creature summoned has the acid, cold, electricity, sonic, or spirit trait, you can deal damage of that type instead.' },
      { name: 'Irresistible Magic', level: 6, desc: 'You’ve studied ways of overcoming the innate defenses against magic that dragons, otherworldly beings, and certain other powerful creatures have. Any creature that has a status bonus to saving throws against magic reduces that bonus by 1 against your spells.' },
      { name: 'Split Slot', level: 6, desc: 'You can prepare two spells in one slot, giving you the freedom to choose the spell when you cast it. When you prepare your spells for the day, you can choose one spell slot at least 1 rank lower than the highest-rank spell you can cast and prepare two spells in that slot. When you Cast a Spell from that slot, choose which spell to cast. Once you’ve chosen, the unused spell dissipates as though you hadn’t prepared it at all—for example, it isn’t available for use with Drain Bonded Item.' },
      { name: 'Steady Spellcasting', level: 6, desc: 'You don’t lose spells easily. If a reaction would disrupt your spellcasting action, attempt a DC 15 flat check. If you succeed, your action isn’t disrupted.' },
      { name: 'Advanced School Spell', level: 8, desc: 'You gain access to the advanced teachings of your arcane institution, learning a powerful new school spell. You gain the advanced school spell for your arcane school.' },
      { name: 'Bond Conservation', action: '1', level: 8, desc: 'Requirements - The last action you used was to Cast a Spell enabled by Drain Bonded Item\nBy efficiently and carefully manipulating the arcane energies unleashed by your bonded item, you can conserve just enough power to cast another spell, though this second spell is slightly weaker. You gain an extra use of Drain Bonded Item. You can use it to cast a spell 2 or more ranks lower than the previous spell, and must use it before the end of your next turn or you lose it.' },
      { name: 'Form Retention', level: 8, desc: 'You have trained your mind and body to tolerate polymorph magic for longer periods of time, so long as you prepare for the change appropriately. When preparing a polymorph spell that lasts 1 minute and grants a battle form, you can prepare the spell in a slot 2 ranks higher than normal. This doesn’t grant any of the normal benefits of heightening a spell, but the spell lasts up to 10 minutes. For example, if you prepared animal form in a 4th-rank slot with Form Retention, you would cast a 2nd-rank animal form that lasts for up to 10 minutes. If the spell can be Dismissed, that doesn’t change.' },
      { name: 'Knowledge Is Power', level: 8, desc: 'Your academic knowledge about a creature allows you to subtly alter your magic to defeat them. When you critically succeed at a Recall Knowledge check about a creature, you can invoke your knowledge to make the creature take a –1 circumstance penalty to either AC and saves against the next attack you make against it, or the next spell you cast that it needs to defend against. The creature takes the same penalty to its attack or DC the next time it attacks against you or causes you to attempt a save against one of its effects.\nIf you share this information with your allies, they gain the benefits as well. If not used, the bonuses end after 1 minute.' },
    ] },
  { key: 'cleric', name: 'Cleric', desc: 'Deities work their will upon the world in infinite ways, and you serve as one of their most stalwart mortal servants. Blessed with divine magic, you live the ideals of your faith, adorn yourself with the symbols of your church, and train diligently to wield your deity’s favored weapon. Your spells might protect and heal your allies, or they might punish foes and enemies of your faith, as your deity wills. Yours is a life of devotion, spreading the teachings of your faith through both word and deed.', book: 'player-core', hp: 8, keyAbility: ['wis'], fixedSkills: ['religion'],
    saves: { fort: 1, ref: 1, will: 2 }, perception: 1, classDC: 1,
    skillsTrainedCount: 2, weapons: 'Trained in simple weapons and your deity’s favored weapon.', armor: 'Trained in unarmored defense.',
    proficiencies: { perception: 'Trained', saves: { fort: 'Trained', ref: 'Trained', will: 'Expert' }, skills: ['Trained in Religion', 'Trained in one skill determined by your choice of deity', 'Trained in a number of additional skills equal to 2 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in your deity’s favored weapon', 'Trained in unarmed attacks'], defenses: ['Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: { tradition: 'Divine', keyAbility: 'wis', type: 'prepared-or-spontaneous' },
    deityRequired: true,
    subclassLabel: 'Doctrine',
    subclasses: [
      { key: 'cloistered', name: 'Cloistered Cleric', desc: 'You are a cleric of the cloth, focusing on divine magic and your connection to your deity’s domains.' },
      { key: 'warpriest', name: 'Warpriest', desc: 'Train in the militant doctrine of your church, focusing on both spells and battle.' },
    ],
    features: [{ name: "Doctrine", desc: "Choose Cloistered Cleric or Warpriest, granting extra proficiency or combat training." }, { name: "Divine Font", desc: "Through your deity's blessing, you gain additional spells that channel either the life force called vitality or its counterforce, the void. When you prepare your spells each day, you can prepare additional heal or harm spells, depending on your deity. The divine font spell your deity provides is listed in the Divine Font entry for your deity; if both are listed, you can choose between heal or harm. Once you choose, you can't change your choice short of divine intervention. You gain 4 additional spell slots each day at your highest rank of cleric spell slots. You can prepare only heal spells in these slots. At 5th level, the number of additional slots increases to 5, and at 15th level, the total number of additional slots increases to 6." }, { name: "Anathema", desc: "Acting against your deity’s edicts can cost you your divine powers." }],
    feats: [
      { name: 'Deadly Simplicity', level: 1, reqFavoredWeaponCategory: ['Simple', 'Unarmed'], desc: 'When you are wielding your deity’s favored weapon, increase the damage die size of that weapon by one step.\nIf your deity’s favored weapon is an unarmed attack (such as a fist, if you worship Irori) and its damage die is smaller than d6, instead increase its damage die size to d6.' },
      { name: 'Divine Castigation', level: 1, reqSanctified: true, desc: 'Your deity’s grace doesn’t extend to your sworn enemies. When you cast a harm or heal spell, you can add your holy or unholy trait to it. If you do, the spell deals damage to creatures with the opposing trait, even if it wouldn’t normally damage them. The spell deals spirit damage when used this way. For example, if you are holy, you could add the holy trait to a heal spell and deal spirit damage to a fiend that has the unholy trait.' },
      { name: 'Domain Initiate', level: 1, desc: 'Your deity bestows a special spell related to their powers. Select one domain —a subject of particular interest to you within your religion—from your deity’s list. You gain an initial domain spell for that domain, a spell unique to the domain and not available to other clerics.\nDomain spells are a type of focus spell. It costs 1 Focus Point to cast a focus spell, and you start with a focus pool of 1 Focus Point. You refill your focus pool during your daily preparations, and you can regain 1 Focus Point by spending 10 minutes using the Refocus activity to pray to your deity or do service toward their causes.\nFocus spells are automatically heightened to half your level rounded up, much like cantrips. Focus spells don’t require spell slots, and can’t be cast using spell slots. Your focus pool can hold one Focus Point for each focus spell you have, up to 3 points. The full rules for focus spells appear here.\nSpecial - You can select this feat multiple times, selecting a different domain each time and gaining its domain spell.' },
      { name: 'Harming Hands', level: 1, reqFont: 'harm', desc: 'The mordant power of your void energy grows. When you cast harm, you roll d10s instead of d8s.' },
      { name: 'Healing Hands', level: 1, reqFont: 'heal', desc: 'Your vitality is even more vibrant and restorative. When you cast heal, you roll d10s instead of d8s.' },
      { name: 'Premonition of Avoidance', level: 1, action: 'R', desc: 'Trigger - You are about to roll a saving throw against a hazard\nYour deity grants you a moment’s foresight. You gain a +2 circumstance bonus to the triggering saving throw.' },
      { name: 'Reach Spell', action: '1', level: 1, desc: 'You can extend your spells’ range. If the next action you use is to Cast a Spell that has a range, increase that spell’s range by 30 feet. As is standard for increasing spell ranges, if the spell normally has a range of touch, you extend its range to 30 feet.' },
      { name: 'Cantrip Expansion', level: 2, desc: 'Study broadens your range of simple spells.\nPrepared Caster (Cleric, Wizard, etc.) - You can prepare two additional cantrips each day.\nSpontaneous Caster (Bard, Sorcerer, etc.) - Add two additional cantrips from your spell list to your repertoire.' },
      { name: 'Communal Healing', level: 2, desc: 'You’re an exceptional conduit for vitality and, as you channel it through you, you can divert some to heal yourself or another creature. When you cast the heal spell to heal a single creature, choose another willing living creature within range of your heal to regain Hit Points equal to the heal spell’s rank.' },
      { name: 'Emblazon Armament', level: 2, desc: 'Carefully etching a sacred image into a physical object, you steel yourself for battle. You can spend 10 minutes emblazoning a symbol of your deity upon a weapon or shield. The symbol doesn’t fade until 1 year has passed, but if you Emblazon an Armament, any symbol you previously emblazoned, and any symbol already emblazoned on that item instantly disappears. The emblazoned item is a religious symbol of your deity in addition to its normal purpose, and it gains another benefit determined by the type of item. The benefit applies only to followers of the deity the symbol represents, but others can use the item normally.\nShield - The shield gains a +1 status bonus to its Hardness. (This causes it to reduce more damage with the Shield Block reaction.).\nWeapon - The wielder gains a +1 status bonus to damage rolls with the weapon.' },
      { name: 'Panic the Dead', level: 2, desc: 'Vitality strikes terror in the undead. When you use a heal spell to damage undead, any undead that fails its saving throw is also frightened 1. If it critically failed, the creature also gains the fleeing condition until the start of your next turn. Mindless undead are not immune to this effect due to being mindless.' },
      { name: 'Rapid Response', level: 2, action: 'R', desc: 'Trigger - An ally is reduced to 0 Hit Points\nYou work quickly in emergencies. You Stride towards the triggering ally. You gain a +10-foot circumstance bonus to your Speed during this movement.' },
      { name: 'Sap Life', level: 2, desc: 'You draw the life force out of your enemies. When you cast a harm spell and damage at least one living creature, you regain Hit Points equal to the spell rank of your harm spell. If you aren’t a living creature, you gain no benefit from this feat.' },
      { name: 'Versatile Font', level: 2, reqFont: 'any', reqDeityBothFonts: true, desc: 'As you explore your deity’s aspects, you move beyond restrictions on healing or harming. You can prepare either harm or heal in the spell slots gained from the harmful font or healing font.' },
      { name: 'Warpriest’s Armor', level: 2, reqSubclass: 'warpriest', desc: 'Your training has helped you adapt to ever-heavier armor. You are trained in heavy armor. Whenever you gain a class feature that grants you expert or greater proficiency in medium armor, you also gain that proficiency in heavy armor. You treat armor you wear of 2 Bulk or higher as though it were 1 Bulk lighter (to a minimum of 1 Bulk).' },
      { name: 'Channel Smite', action: '2', level: 4, desc: 'Cost - Expend a harm or heal spell\nYou siphon the energies of life and death through a melee attack and into your foe. Make a melee Strike. On a hit, you cast the 1-action version of the expended spell to damage the target, in addition to the normal damage from your Strike. The target automatically gets a failure on its save (or a critical failure if your Strike was a critical hit). The spell doesn’t have the manipulate trait when cast this way.\nThe spell is expended with no effect if your Strike fails or hits a creature that isn’t damaged by that energy type (such as if you hit a non-undead creature with a heal spell).' },
      { name: 'Directed Channel', level: 4, desc: 'You can shape the energy you channel in a single direction. When you cast a version of harm or heal that has an area, you can make its area a 60-foot cone instead of a 30-foot emanation.' },
      { name: 'Divine Infusion', action: '1', level: 4, desc: 'You pour energy into the subject of your healing to empower its attacks. If the next action you use is to cast harm or heal to restore Hit Points to a single creature, the target then deals an additional 1d6 damage with its melee weapons and unarmed attacks until the end of its next turn. The damage type is void if you cast harm and vitality if you cast heal.\nIf the spell cast is at least 5th rank, this damage increases to 2d6, and if the spell is at least 8th rank, the damage increases to 3d6.' },
      { name: 'Raise Symbol', action: '1', level: 4, desc: 'Requirements - You are wielding a religious symbol\nYou present your religious symbol emphatically. You gain a +2 circumstance bonus to saving throws until the start of your next turn. While it’s raised, if you roll a success at a saving throw against a vitality or void effect, you get a critical success instead.\nIf the religious symbol you’re raising is a shield, such as with Emblazon Armaments, you gain the effects of Raise a Shield when you use this action and the effects of this action when you Raise a Shield.' },
      { name: 'Restorative Strike', action: '2', level: 4, desc: 'Requirements - You have a harm or heal spell you can cast\nYou balance both sides of the scales, restoring yourself while striking a foe. Cast a 1-action harm or heal spell to heal yourself, expending the spell normally. It loses the manipulate trait when cast this way. Then make a melee Strike. If you make this Strike with your deity’s favored weapon, you gain a +1 status bonus to the attack roll.\nIf the Strike hits, you can target a second willing creature to heal the same amount from the spell. This creature can be outside of the spell’s range, provided it’s adjacent to the enemy you hit.' },
      { name: 'Sacred Ground', level: 4, reqFont: 'any', desc: 'Frequency - once per 10 minutes\nYou pray continuously for 1 minute to call a subtle shadow of your deity’s realm over a 30-foot burst centered on you. It lasts for 10 minutes, and a creature that remains in the area for the entire 10 minutes regains Hit Points equal to your level. If you have a healing font, this activity has the healing and vitality traits and heals living creatures.\nIf you have a harmful font, this activity has the healing and void traits and heals undead creatures (or other creatures with void healing). Clerics with Versatile Font can choose either or both. It can’t damage creatures in any case.' },
      { name: 'Cast Down', action: '1', level: 6, desc: 'The sheer force of your faith can bring a foe crashing down. If the next action you use is to cast harm or heal to damage one creature, the target is knocked prone if it takes any damage from the spell. If the target critically fails its save against the spell, it also takes a –10-foot status penalty to its Speed for 1 minute.' },
      { name: 'Divine Rebuttal', level: 6, action: 'R', desc: 'Trigger - Your ally is about to roll a saving throw against a magical ability of a creature you’re adjacent to\nRequirements - You are wielding your deity’s favored weapon\nYou strive against magical threats physically and spiritually. You can Strike the adjacent creature with your deity’s favored weapon. If you are holy or unholy, the Strike gains that trait. If your Strike hits, all your allies gain a +2 circumstance bonus to the triggering saving throw (or a +3 circumstance bonus on a critical hit).' },
      { name: 'Divine Weapon', action: 'F', level: 6, desc: 'Frequency - once per turn\nTrigger - You finish Casting a Spell using one of your divine spell slots on your turn\nYou siphon residual spell energy into a weapon you’re wielding. Until the end of your turn, the weapon deals an additional 1d4 spirit damage. If you are holy or unholy, Strikes with the weapon also gain that trait, and the additional damage increases to 2d4 against creatures of the opposing trait.' },
      { name: 'Magic Hands', level: 6, reqFeats: ['Healing Hands'], desc: 'The blessing of your deity heightens your healing ability, integrating magical healing with the mundane. When you succeed at a Medicine check to Treat Wounds, you can roll d10s instead of d8s for the healing and add a status bonus to the healing equal to your level.' },
      { name: 'Selective Energy', level: 6, desc: 'As you call down divine power, you can prevent some enemies from benefiting or some allies from being hurt. When you cast a version of harm or heal that has an area, you can designate up to 5 creatures in the area. They are not targeted by the spell.' },
      { name: 'Steady Spellcasting', level: 6, desc: 'You don’t lose spells easily. If a reaction would disrupt your spellcasting action, attempt a DC 15 flat check. If you succeed, your action isn’t disrupted.' },
      { name: 'Advanced Domain', level: 8, reqFeats: ['Domain Initiate'], desc: 'Your prayers have unlocked deeper secrets of your deity’s domain. You gain an advanced domain spell from one of your domains for which you have an initial domain spell.\nSpecial - You can select this feat multiple times. Each time, you must select a different advanced domain spell.' },
      { name: 'Cremate Undead', level: 8, desc: 'Your overwhelming vitality sets undead alight. When you use a heal spell to damage undead, each undead that takes damage also takes persistent fire damage equal to the spell’s rank.' },
      { name: 'Emblazon Energy', level: 8, reqFeats: ['Emblazon Armament'], desc: 'With elemental forces, you make your emblazoned symbols more potent. When you Emblazon an Armament, you can choose from the following effects instead of the effects listed in that feat. These effects have the same restrictions as the base options.\nShield - Choose acid, cold, electricity, fire, or sonic. The wielder gains the shield’s circumstance bonus to saving throws against that damage type and can use Shield Block against damage of that type. The shield also gains resistance to that damage type equal to half your level if you have a domain spell with a trait matching that type (such as fire ray).\nWeapon - Choose acid, cold, electricity, fire, or sonic. The weapon deals an extra 1d4 damage of that type. Increase this extra damage to 1d6 if you have a domain spell with a trait matching that type (such as fire ray).' },
      { name: 'Martyr', action: '1', level: 8, desc: 'You go to extreme lengths to support your allies, even when it means bringing harm to yourself. If your next action is to cast harm or heal to restore Hit Points to a single ally, you can channel your own vitality along with the spell. You lose 1d8 Hit Points per rank of the spell, which can’t be reduced or mitigated in any way, and your ally regains an equal number of Hit Points' },
      { name: 'Restorative Channel', level: 8, reqFont: 'heal', desc: 'You can remove conditions with divine grace. You can sacrifice one heal spell you’ve prepared in your extra slots from your healing font to cast one of the following spells instead: cleanse affliction, clear mind, sound body, or sure footing. The spell is heightened to the same rank as the spell you sacrificed.' },
      { name: 'Sanctify Armament', action: '1', level: 8, reqSanctified: true, desc: 'You touch a weapon and bring it into concordance with your deity. For 1 round, that weapon gains your holy or unholy trait. It also deals an additional 2d6 spirit damage to creatures of the opposed trait. For example, if you are holy, the weapon would deal an extra 2d6 spirit damage to unholy creatures.\nIf you use Sanctify Armament again, any previous use of it expires.' },
      { name: 'Surging Focus', action: 'F', level: 8, desc: 'Frequency - once per day\nTrigger - An ally you can see falls to 0 Hit Points\nWhen an ally you can see falls in battle, your surge of righteous indignation allows you to draw upon untapped reserves of divine power. You instantly regain 1 Focus Point.' },
      { name: 'Void Siphon', level: 8, desc: 'The raw energy of the Void saps the essence of the living. Any living creature that critically fails its save against a harm spell you cast is drained 1.' },
      { name: 'Zealous Rush', level: 8, action: 'R', desc: 'Trigger - You cast a divine spell that takes 1 action or more to cast and that affects only you or your equipment\nYou bless yourself on the move. Stride up to 10 feet. If the spell took 2 or more actions, you can Stride up to your full Speed instead.' },
    ] },
  { key: 'ranger', name: 'Ranger', desc: 'Some rangers believe civilization wears down the soul, but still needs to be protected from wild creatures. Others say nature needs to be protected from the greedy, who wish to tame its beauty and plunder its treasures. You could champion either goal, or both. You might be a scout, tracker, or hunter of fugitives or beasts, haunting the edge of civilization or exploring the wilds. You know how to live off the land and are skilled at spotting and taking down both opportune prey and hated enemies.', book: 'player-core', hp: 10, keyAbility: ['str', 'dex'],
    saves: { fort: 2, ref: 2, will: 1 }, perception: 2, classDC: 1,
    skillsTrainedCount: 4, weapons: 'Trained in simple and martial weapons.', armor: 'Trained in light and medium armor.',
    proficiencies: { perception: 'Expert', saves: { fort: 'Expert', ref: 'Expert', will: 'Trained' }, skills: ['Trained in Nature', 'Trained in Survival', 'Trained in a number of additional skills equal to 4 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in martial weapons', 'Trained in unarmed attacks'], defenses: ['Trained in light armor', 'Trained in medium armor', 'Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: null,
    features: [{ name: "Hunt Prey", desc: "Designate a creature as your prey, gaining benefits against it as you track and attack it." }, { name: "Ranger's Focus", desc: "Refocus by using Hunt Prey against your current prey." }],
    feats: [
      { name: 'Animal Companion', level: 1, desc: 'You gain the service of a young animal companion that travels with you on your adventures and obeys any simple commands you give it to the best of its abilities. See Animal Companions for more information.\nRanger - When you Hunt Prey, your animal companion gains the action’s benefits and your hunter’s edge benefit if you have one.' },
      { name: 'Crossbow Ace', level: 1, action: '1', desc: 'Requirements - You are wielding a crossbow with reload 1 or higher\nYour deep understanding of the crossbow allows you to reload efficiently while moving yourself out of the line of return fire. Either Create a Diversion or Take Cover, then Interact to reload. As normal, you must meet the requirements to Take Cover; you must be prone, benefiting from cover, or near a feature that allows you to Take Cover' },
      { name: 'Hunted Shot', level: 1, action: '1', desc: 'Requirements - You are wielding a ranged weapon with reload 0\nYou take two quick shots against the one you hunt. Make two Strikes against your prey with the required weapon. If both hit the same creature, combine their damage for the purpose of resistances and weaknesses. Apply your multiple attack penalty to each Strike normally' },
      { name: 'Initiate Warden', level: 1, desc: 'You’ve trained with one of the ranger sects known as wardens, who practice a specialized type of primal magic. You gain your choice of one warden spell from the initial warden spells (or another you have access to).\nSpecial - You can take this feat multiple times, choosing a different initial warden spell each time.' },
      { name: 'Monster Hunter', level: 1, desc: 'You quickly assess your prey and apply what you know. As part of the action used to Hunt your Prey, you can attempt a check to Recall Knowledge about your prey. When you critically succeed at identifying your hunted prey with Recall Knowledge, you note a weakness in the creature’s defenses in addition to any other benefits. You gain a +1 circumstance bonus to your next attack roll against that prey, and any ally you tell gains the same benefit. You can give bonuses from Monster Hunter only once per day against a particular creature.' },
      { name: 'Twin Takedown', level: 1, action: '1', desc: 'Requirements - You are wielding two melee weapons, each in a different hand\nYou swiftly attack your hunted prey with each of your weapons, potentially combining their damage into a single devastating attack. Make two Strikes against your hunted prey, one with each of the required weapons. If both hit the same hunted prey, combine their damage for the purpose of its resistances and weaknesses. Apply your multiple attack penalty to each Strike normally.' },
      { name: 'Animal Empathy', level: 2, desc: 'You have a connection to the creatures of the natural world that allows you to communicate with them on a rudimentary level. You can use Diplomacy to Make an Impression on animals and to make very simple Requests of them. In most cases, wild animals will give you time to make your case.' },
      { name: 'Favored Terrain', level: 2, desc: 'You have studied a specific terrain to overcome its challenges. Choose aquatic, arctic, desert, forest, mountain, plains, sky, swamp, or underground as your favored terrain. When in that terrain, you can ignore the effects of non-magical difficult terrain. If you have the unimpeded journey class feature, you gain a second benefit while in your favored terrain, depending on your choice:\nAquatic - You gain a swim Speed equal to your Speed. If you already had a swim Speed, you instead gain a +10-foot status bonus to your swim Speed.\nArctic - You need to eat and drink only one-tenth as much as usual, you aren’t affected by severe or extreme cold, and you can walk across ice and snow at full Speed without needing to Balance.\nDesert - You need to eat and drink only one-tenth as much as usual, you aren’t affected by severe or extreme heat, and you can walk along sand at full Speed without needing to Balance.\nForest, Mountain, or Underground - You gain a climb Speed equal to your Speed. If you already had a climb Speed, you instead gain a +10-foot status bonus to your climb Speed.\nPlains - You gain a +10-foot status bonus to your land Speed.\nSky - You gain a +10-foot status bonus to your fly Speed, if you have one.\nSwamp - You can move across bogs at full Speed, even if they are deep enough to be greater difficult terrain or to normally require you to Swim.' },
      { name: 'Hunter’s Aim', level: 2, action: '2', desc: 'When you focus on aiming, your attack becomes particularly accurate. Make a ranged weapon Strike against your hunted prey. On this Strike, you gain a +2 circumstance bonus to the attack roll and ignore your prey’s concealed condition and any lesser cover.' },
      { name: 'Monster Warden', level: 2, reqFeats: ['Monster Hunter'], desc: 'You understand how to defend against your prey. When you grant bonuses from Monster Hunter, each creature who benefits also gains a +2 circumstance bonus either to their AC the next time the creature attacks them or to their next saving throw against an effect from that particular creature (whichever comes first.)' },
      { name: 'Quick Draw', level: 2, action: '1', desc: 'You draw your weapon and attack with the same motion. You Interact to draw a weapon, then Strike with that weapon.' },
      { name: 'Advanced Warden', level: 4, reqFeats: ['Initiate Warden'], desc: 'You unlock more powerful primal spells. You gain your choice of one warden spell from the advanced warden spells (or another you have access to).\nSpecial - You can take this feat multiple times, choosing a different advanced warden spell each time.' },
      { name: 'Companion’s Cry', level: 4, reqFeats: ['Animal Companion'], desc: 'You can urge your companion to do its utmost. You can spend 2 actions to Command an Animal instead of 1 when commanding your animal companion. If you do, your animal companion uses an additional action.' },
      { name: 'Disrupt Prey', level: 4, action: 'R', desc: 'Trigger - Your hunted prey is within your reach, and it uses a manipulate action, uses a move action, or leaves a square during a move action it’s using\nMake a melee Strike against your prey. If the attack is a critical hit, you disrupt the triggering action.' },
      { name: 'Far Shot', level: 4, desc: 'Your experience in the field has taught you how to focus your aim at a distance, increasing your accuracy. Double your weapons’ range increments.' },
      { name: 'Favored Prey', level: 4, desc: 'You have studied a specific type of wild creature and can hunt it more easily. When you gain this feat, choose animals, beasts, dragons, or both fungi and plants as your favored prey. When you roll initiative and can see an enemy that belongs to the chosen category, you can Hunt Prey as a free action, designating that enemy.\nYou can use this free action even if you haven’t identified the creature yet with Recall Knowledge. The benefit doesn’t apply against favored enemies disguised as other creatures, and the GM determines whether it applies against a creature disguised as a favored prey' },
      { name: 'Running Reload', level: 4, action: '1', desc: 'You can reload your weapon on the move. You Stride, Step, or Sneak, then Interact to reload.' },
      { name: 'Scout’s Warning', action: 'F', level: 4, desc: 'Trigger - You are about to roll a Perception or Survival check for initiative\nYou visually or audibly warn your allies of danger, granting them each a +1 circumstance bonus to their initiative rolls, or a +2 circumstance bonus if you’re using the Scout exploration activity. Depending on whether you use gestures or call out, this action gains either the visual or the auditory trait, respectively.' },
      { name: 'Twin Parry', level: 4, action: '1', desc: 'Requirements - You are wielding two melee weapons, one in each hand\nYou use your two weapons to parry attacks. You gain a +1 circumstance bonus to AC until the start of your next turn, or a +2 circumstance bonus if either weapon has the parry trait. You lose this circumstance bonus if you no longer meet this feat’s requirement.' },
      { name: 'Additional Recollection', action: 'F', level: 6, desc: 'Trigger - You succeed or critically succeed at a check to Recall Knowledge on your hunted prey\nYou scan the battlefield quickly, remembering critical details about multiple opponents you face. You immediately attempt a check to Recall Knowledge about a different creature you can perceive.' },
      { name: 'Masterful Warden', level: 6, reqFeats: ['Initiate Warden'], desc: 'Your mastery of warden magic increases. You gain your choice of one warden spell from the master warden spells (or another you have access to).\nSpecial - You can take this feat multiple times, choosing a different master warden spell each time.' },
      { name: 'Mature Animal Companion', level: 6, reqFeats: ['Animal Companion'], desc: 'Your animal companion becomes a mature animal companion and gains additional capabilities.\nYour animal companion has greater independence. During an encounter, even if you don’t use the Command an Animal action, your animal companion can still use 1 action that round on your turn to Strike or Stride (or Burrow, Climb, Fly, or Swim if it has that Speed). It can do this at any point during your turn, as long as you aren’t currently taking an action. If it does, that’s all the actions it gets that round—you can’t Command it later.' },
      { name: 'Skirmish Strike', level: 6, action: '1', desc: 'Your feet and weapon move in tandem. Either Step and then Strike, or Strike and then Step.' },
      { name: 'Snap Shot', level: 6, desc: 'You can react with ranged weapons when a creature is in close quarters. You can use a reaction that normally allows you to make a melee weapon Strike to instead make a ranged weapon Strike. You must be Striking an adjacent target. If necessary for the reaction’s trigger, you treat your ranged weapon as if it had a reach of 5 feet. If the reaction has other requirements, such as wielding a specific kind of weapon, Snap Shot doesn’t allow you to ignore them; it allows you only to replace a melee weapon Strike with a ranged weapon Strike.' },
      { name: 'Swift Tracker', level: 6, reqSkills: [{ skill: 'survival', rank: 2 }], reqFeats: ['Experienced Tracker'], desc: 'Your keen eyes catch signs of passage even when you’re moving. You can move at your full Speed while you Track. If you have master proficiency in Survival, you don’t need to attempt a new Survival check every hour while Tracking. If you have legendary proficiency in Survival, you can use another exploration activity while Tracking.\nIf you roll Survival for initiative while tracking your hunted prey, when you start your first turn of the encounter, you can Stride toward your hunted prey as a free action.' },
      { name: 'Blind-Fight', level: 8, reqPerception: 3, desc: 'Your battle instincts make you more aware of concealed and invisible opponents. You don’t need to succeed at a flat check to target concealed creatures. You’re not off-guard to creatures that are hidden from you (unless you’re off-guard to them for reasons other than the hidden condition), and you need only a successful DC 5 flat check to target a hidden creature.\nWhile you’re adjacent to an undetected creature of your level or lower, it is instead only hidden from you' },
      { name: 'Deadly Aim', level: 8, action: '1', desc: 'You aim for your prey’s weak spots, making your shot more challenging but dealing more damage if you hit. Make a ranged Strike against your hunted prey at a –2 penalty. You gain a +4 circumstance bonus to damage on that Strike. This bonus increases to +6 at 11th level and +8 at 15th level.' },
      { name: 'Hazard Finder', level: 8, desc: 'You have an intuitive ability to sense hazards. You gain a +1 circumstance bonus to Perception checks to find traps and hazards, to AC against their attacks, and to saves against their effects. You can find hazards that would normally require you to Search even if you aren’t Searching.' },
      { name: 'Terrain Master', level: 8, reqSkills: [{ skill: 'survival', rank: 3 }], reqFeats: ['Favored Terrain'], desc: 'You are able to adapt to your surroundings in any natural terrain. You can spend 1 hour practicing in your current terrain in order to make it your favored terrain, replacing your current favored terrain temporarily. If you spend a full day out of the new favored terrain, your favored terrain reverts back to your original choice when you took the Favored Terrain feat.' },
      { name: 'Warden’s Boon', level: 8, action: '1', desc: 'You point out vulnerabilities present in your hunted prey, granting the benefits listed in Hunt Prey and your hunter’s edge to an ally until the end of their next turn. Depending on whether you call out or use gestures, this action gains either the auditory or visual trait.' },
    ] },
  { key: 'barbarian', name: 'Barbarian', desc: 'Rage consumes you in battle. You delight in wreaking havoc and using powerful weapons to carve through your enemies, relying on astonishing durability without needing complicated techniques or rigid training. Your rages draw upon a vicious instinct, which you might associate with an animal, a spirit, or some part of yourself. To many barbarians, brute force is a hammer and every problem looks like a nail, whereas others try to hold back the storm of emotions inside them and release their rage only when it matters most.', book: 'player-core-2', hp: 12, keyAbility: ['str'],
    saves: { fort: 2, ref: 1, will: 2 }, perception: 2, classDC: 1,
    skillsTrainedCount: 3, weapons: 'Trained in simple and martial weapons.', armor: 'Trained in light and medium armor.',
    proficiencies: { perception: 'Expert', saves: { fort: 'Expert', ref: 'Trained', will: 'Expert' }, skills: ['Trained in Athletics', 'Trained in a number of additional skills equal to 3 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in martial weapons', 'Trained in unarmed attacks'], defenses: ['Trained in light armor', 'Trained in medium armor', 'Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: null,
    // Player Core 2 instincts (Instincts.aspx). Each desc lists the 1st-level instinct ability plus the
    // 7th-level specialization ability and the damage types covered by 9th-level Raging Resistance.
    // An instinct with `choices` (Animal, Dragon) needs a further pick at creation, stored as the
    // character's subclassChoiceKey; the sheet slots the chosen entry in as a line after the intro.
    subclassLabel: 'Instinct',
    subclasses: [
      { key: 'animal', name: 'Animal Instinct', desc: 'Your rage unleashes the ferocity of a wild predator, manifesting as brutal unarmed attacks.\nBestial Rage - While raging, you gain your chosen animal\'s unarmed attacks (in the brawling group) but can\'t use weapons, and your Rage action gains the morph and primal traits.\nSpecialization Ability (7th) - Your animal\'s unarmed attacks increase their damage die by one step, and Rage adds 5 damage to them instead of 2 (12 with greater weapon specialization).\nRaging Resistance (9th) - While raging, you resist piercing and slashing damage.',
        choiceLabel: 'Choose an Animal',
        choices: [
          { key: 'ape', name: 'Ape', desc: 'Fist 1d10 bludgeoning (grapple, unarmed)' },
          { key: 'bear', name: 'Bear', desc: 'Jaws 1d10 piercing (unarmed); Claw 1d6 slashing (agile, unarmed)' },
          { key: 'bull', name: 'Bull', desc: 'Horn 1d10 piercing (shove, unarmed)' },
          { key: 'cat', name: 'Cat', desc: 'Jaws 1d10 piercing (unarmed); Claw 1d6 slashing (agile, unarmed)' },
          { key: 'deer', name: 'Deer', desc: 'Antler 1d10 piercing (grapple, unarmed)' },
          { key: 'frog', name: 'Frog', desc: 'Jaws 1d10 bludgeoning (unarmed); Tongue 1d6 bludgeoning (agile, unarmed)' },
          { key: 'shark', name: 'Shark', desc: 'Jaws 1d10 piercing (grapple, unarmed)' },
          { key: 'snake', name: 'Snake', desc: 'Fangs 1d10 piercing (grapple, unarmed)' },
          { key: 'wolf', name: 'Wolf', desc: 'Jaws 1d10 piercing (trip, unarmed)' },
        ] },
      { key: 'dragon', name: 'Dragon Instinct', desc: 'You channel the fury of a mighty dragon, perhaps because your culture reveres draconic majesty, or because you bathed in dragon\'s blood or watched a wyrm raze your home.\nDraconic Rage - When you Rage, you can increase Rage\'s additional damage from 2 to 4 and change its type to your dragon\'s breath damage type instead of your weapon or unarmed attack\'s type. If you do, your Rage action gains your dragon\'s tradition trait, plus the matching damage-type trait where one applies.\nSpecialization Ability (7th) - Draconic rage damage increases from 4 to 8 (16 with greater weapon specialization).\nRaging Resistance (9th) - While raging, you resist piercing damage and your dragon\'s breath damage type.',
        choiceLabel: 'Choose a Dragon Type',
        choices: [
          { key: 'adamantine', name: 'Adamantine', desc: 'Primal tradition, bludgeoning breath' },
          { key: 'conspirator', name: 'Conspirator', desc: 'Occult tradition, poison breath' },
          { key: 'diabolic', name: 'Diabolic', desc: 'Divine tradition, fire breath' },
          { key: 'empyreal', name: 'Empyreal', desc: 'Divine tradition, spirit breath' },
          { key: 'fortune', name: 'Fortune', desc: 'Arcane tradition, force breath' },
          { key: 'horned', name: 'Horned', desc: 'Primal tradition, poison breath' },
          { key: 'mirage', name: 'Mirage', desc: 'Arcane tradition, mental breath' },
          { key: 'omen', name: 'Omen', desc: 'Occult tradition, mental breath' },
        ] },
      { key: 'fury', name: 'Fury Instinct', desc: 'Your rage wells up from somewhere deep and wholly personal, and you wield it however you see fit.\nUnstoppable Frenzy - Rage\'s additional damage increases from 2 to 3, and you gain a bonus 1st-level barbarian feat.\nSpecialization Ability (7th) - Rage\'s additional damage increases from 3 to 7 (13 with greater weapon specialization).\nRaging Resistance (9th) - While raging, you resist physical damage from weapons, but not physical damage from other sources such as unarmed attacks.', grantsFeat: { pool: 'class', maxLevel: 1 } },
      { key: 'giant', name: 'Giant Instinct', desc: 'Your rage grants you the raw might and size of a giant, whether you admire giants, scorn them, or simply seem larger than life to those around you.\nTitan Mauler - If you\'re Small or Medium, you can use weapons built for a Large creature (otherwise, one size larger than you), both normally and while raging. You start with one such weapon for free: a common melee or ranged weapon with a Price of 9 gp or less before the size adjustment. It\'s your personal weapon, has no value if sold unless you add runes to it, and has the normal Bulk for its size. While wielding a larger weapon in combat, Rage\'s additional damage increases from 2 to 6, but you\'re clumsy 1 from its unwieldy size, and you can\'t remove or ignore that condition while wielding it.\nSpecialization Ability (7th) - Rage damage with a larger weapon increases from 6 to 10 (18 with greater weapon specialization).\nRaging Resistance (9th) - While raging, you resist bludgeoning damage and your choice of cold, electricity, or fire, chosen when you gain this ability.' },
      { key: 'spirit', name: 'Spirit Instinct', desc: 'Your rage takes the form of spiritual possession, whether you\'re attuned to the spirits around you, venerate ancestors or apparitions, or are haunted by the ghost of someone you knew.\nSpirit Rage - Each time you Rage, you can increase Rage\'s additional damage from 2 to 3 and change its type to spirit instead of your weapon or unarmed attack\'s type. If you do, your weapon or unarmed attack gains the effects of a ghost touch rune, and your Rage action gains the divine and spirit traits.\nSpecialization Ability (7th) - Spirit rage damage increases from 3 to 7 (13 with greater weapon specialization).\nRaging Resistance (9th) - While raging, you resist void damage, as well as all damage from the attacks and abilities of undead creatures, regardless of its type.' },
      { key: 'superstition', name: 'Superstition Instinct', desc: 'A deep distrust of magic drives you to shun spellcraft and hunt those who practice it, whether it stems from a superstitious upbringing, a magical accident, or a bloodline known for resisting magic.\nAnathema - Learning or Casting a Spell, or wielding or using an item that can be activated to Cast a Spell. If you violate this, you lose this instinct\'s abilities and any feats that require it until you spend 1 day of downtime re-centering yourself; your other barbarian abilities remain.\nSuperstitious Resilience - While raging, you gain a +2 status bonus to all saves against magic, and Rage\'s additional damage increases from 2 to 3 (4 against creatures you\'ve seen Cast a Spell within the last hour). When you Rage, you regain Hit Points equal to the temporary Hit Points it granted, and can\'t regain HP this way again for 10 minutes. If you willingly accept the effects of a magic spell or effect while raging, you become frightened 1 and can\'t reduce that condition below 1 while the effect lasts.\nSpecialization Ability (7th) - Rage damage increases from 3 to 7, or 8 against creatures you\'ve seen Cast a Spell within the last hour (13 or 16 with greater weapon specialization).\nRaging Resistance (9th) - Choose two associated traditions: arcane and occult, arcane and primal, divine and occult, or divine and primal. While raging, you resist all damage from spells of those traditions, regardless of its type.' },
    ],
    features: [
      { name: 'Rage', action: '1', desc: 'Requirements - You aren\'t fatigued or raging.\nYou tap into your inner fury and begin raging, gaining temporary Hit Points equal to your level plus your Constitution modifier. While raging, you deal 2 additional damage on melee Strikes (halved if your weapon or unarmed attack is agile), and you can\'t use actions with the concentrate trait unless they also have the rage trait, though you can still Seek.\nDuration - Rage lasts for 1 minute, until you fall unconscious, or until the encounter ends, whichever comes first. You can\'t voluntarily stop raging.\nAfter Raging - You lose any remaining temporary Hit Points from Rage, and you can\'t gain temporary Hit Points from the Rage action again for 1 minute.' },
      { name: 'Quick-Tempered', action: 'F', desc: 'Trigger - You roll initiative.\nRequirements - You aren\'t encumbered or wearing heavy armor.\nAs long as you can move freely, your fury is instinctive and instantaneous. You Rage.' },
      { name: 'Instinct', desc: 'Choose an instinct that shapes how your rage manifests and grants additional benefits.' },
    ],
    feats: [{ name: 'Acute Vision', desc: 'When you are raging, your visual senses improve, granting you darkvision.' }, { name: 'Moment of Clarity', action: '1', desc: 'You push back your rage for a moment in order to think clearly. Until the end of this turn, you can use actions with the concentrate trait even if those actions don’t have the rage trait.' }] },
  { key: 'bard', name: 'Bard', desc: 'You are a master of artistry, a scholar of hidden secrets, and a captivating persuader. Using powerful performances, you influence minds and elevate souls to new levels of heroics. You might use your powers to become a charismatic leader, or perhaps you might instead be a counselor, manipulator, scholar, scoundrel, or virtuoso. While your versatility leads some to consider you a beguiling ne’er-do-well and a jack-of-all-trades, it’s dangerous to dismiss you as a master of none.', book: 'player-core', hp: 8, keyAbility: ['cha'],
    saves: { fort: 1, ref: 1, will: 2 }, perception: 2, classDC: 1,
    skillsTrainedCount: 4, weapons: 'Trained in simple and martial weapons.', armor: 'Trained in light armor.',
    proficiencies: { perception: 'Expert', saves: { fort: 'Trained', ref: 'Trained', will: 'Expert' }, skills: ['Trained in Occultism', 'Trained in Performance', 'Trained in a number of additional skills equal to 4 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in martial weapons', 'Trained in unarmed attacks'], defenses: ['Trained in light armor', 'Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: { tradition: 'Occult', keyAbility: 'cha', type: 'spontaneous' },
    subclassLabel: 'Muse',
    subclasses: [
      { key: 'enigma', name: 'Enigma', desc: 'Support allies with knowledge alongside inspiration and occult support. Grants Bardic Lore.' },
      { key: 'maestro', name: 'Maestro', desc: 'An inspiration to your allies, confident in your musical and oratorical abilities. Grants Lingering Composition.' },
      { key: 'polymath', name: 'Polymath', desc: 'Interested in a wide array of topics but rarely dedicated to any one. Grants Versatile Performance.' },
      { key: 'warrior', name: 'Warrior', desc: 'Train for battle in addition to performance, preparing allies for the dangers of combat. Grants Martial Performance.' },
    ],
    features: [{ name: "Composition Spells", desc: "Cast unique spells fueled by Performance that require you to maintain the performance." }, { name: "Muses", desc: "Choose a muse that grants you a signature skill and an occult spell." }],
    feats: [
      { name: 'Bardic Lore', level: 1, reqSubclass: 'enigma', desc: 'Your studies make you informed on every subject. You are trained in Bardic Lore, a special Lore skill that can be used only to Recall Knowledge, but on any topic. If you have legendary proficiency in Occultism, you gain expert proficiency in Bardic Lore, but you can’t increase your proficiency rank in Bardic Lore by any other means.' },
      { name: 'Hymn of Healing', level: 1, desc: 'You learn the hymn of healing composition spell, which imbues your music with rich melodies that help your allies recover from harm.' },
      { name: 'Lingering Composition', level: 1, reqSubclass: 'maestro', desc: 'By adding a flourish, you make your compositions last longer. You learn the lingering composition focus spell.' },
      { name: 'Martial Performance', level: 1, reqSubclass: 'warrior', desc: 'Your muse has taught you how to handle a wider variety of weapons than most bards, empowering you to effortlessly blend your performance into combat tools. When you have a courageous anthem composition cantrip active, and you damage an enemy with a Strike, the spell’s duration is extended by 1 round. You can extend an individual casting only once in this way.\nIf you gain the rallying anthem or song of strength composition cantrips, you can apply this benefit to those cantrips as well.' },
      { name: 'Reach Spell', action: '1', level: 1, desc: 'You can extend your spells’ range. If the next action you use is to Cast a Spell that has a range, increase that spell’s range by 30 feet. As is standard for increasing spell ranges, if the spell normally has a range of touch, you extend its range to 30 feet.' },
      { name: 'Versatile Performance', level: 1, reqSubclass: 'polymath', desc: 'You can rely on the grandeur of your performances rather than ordinary social skills. You can use Performance instead of Diplomacy to Make an Impression and instead of Intimidation to Demoralize. You can also use an acting Performance instead of Deception to Impersonate. In addition, you can use your proficiency rank in Performance to meet the prerequisites of skill feats that require a particular proficiency rank in Deception, Diplomacy, or Intimidation.' },
      { name: 'Well-Versed', level: 1, desc: 'You’re resilient to performative influences that aren’t your own. You gain a +1 circumstance bonus to saving throws against effects with the auditory, illusion, linguistic, sonic, or visual traits.' },
      { name: 'Cantrip Expansion', level: 2, desc: 'Study broadens your range of simple spells.\nPrepared Caster (Cleric, Wizard, etc.) - You can prepare two additional cantrips each day.\nSpontaneous Caster (Bard, Sorcerer, etc.) - Add two additional cantrips from your spell list to your repertoire.' },
      { name: 'Directed Audience', level: 2, desc: 'You can shape the area of your composition spells. Whenever you cast a composition spell whose area is an emanation, you can change the spell’s area to a cone 10 feet larger, to a maximum of twice the original area. For example, you could modify a composition spell that affects a 30-foot emanation to affect a 40-foot cone, but a 5-foot emanation could only become a 10-foot cone.' },
      { name: 'Emotional Push', level: 2, action: 'R', desc: 'Trigger - An enemy you’re aware of fails its save against an emotion spell\nYou prepare to take advantage of your enemy’s sudden change in emotions. The target is off-guard against your next attack before the end of your next turn.' },
      { name: 'Esoteric Polymath', level: 2, reqSubclass: 'polymath', desc: 'You keep a book of occult spells, similar to a wizard ’s spellbook, and can use its spells to supplement your spell repertoire. Add all the spells in your repertoire to this book for free. You can use the Occultism skill to Learn Spells and add them to your spellbook by paying the appropriate cost. During your daily preparations, choose any one spell from your book of occult spells. If that spell is already in your spell repertoire, you can treat it as an additional signature spell that day. If it isn’t in your repertoire, treat it as though it were until your next daily preparations.' },
      { name: 'Loremaster’s Etude', level: 2, reqSubclass: 'enigma', desc: 'You magically unlock memories, making them easier to recall. You learn the loremaster’s etude composition spell.' },
      { name: 'Multifarious Muse', level: 2, desc: 'Your muse doesn’t fall into a single label. Choose a type of muse other than that of your own. You gain a 1st-level feat that requires that muse, and your muse is now also a muse of that type, allowing you to take feats with the other muse as a prerequisite. You don’t gain any of the other effects of the muse you chose.\nSpecial - You can take this feat multiple times. Each time you do, you must choose a different type of muse other than that of your own.', grantsFeat: { pool: 'class-other-subclass' } },
      { name: 'Song of Strength', level: 2, reqSubclass: 'warrior', desc: 'Your performances inspire strength in your allies to aid them at physical tasks. You learn the song of strength composition cantrip.' },
      { name: 'Uplifting Overture', level: 2, reqSubclass: 'maestro', desc: 'You learn the uplifting overture composition cantrip, which aids your allies’ skills with the inspiring nature of your performance.' },
      { name: 'Combat Reading', action: '1', level: 4, desc: 'You use a performer’s cold reading techniques, aura reading, and other tricks to discover your foe’s strengths and weaknesses. The GM rolls a secret Occultism check for you against the Deception or Stealth DC (whichever is higher) of an enemy of your choice who is not concealed from you, hidden from you, or undetected by you, and who is engaged in combat. The GM might apply a penalty for the distance between you and the enemy. The enemy is then temporarily immune to your Combat Reading for 1 day.\nCritical Success - The GM chooses and tells you two of the following pieces of information about the enemy: which of the enemy’s weaknesses is highest, which of the enemy’s saving throws has the lowest modifier, one immunity the enemy has, or which of the enemy’s resistances is highest. In the event of a tie, the GM should pick one at random.\nSuccess - The GM chooses one piece of information from the above list to tell you about the enemy.\nCritical Failure - The GM gives you false information (the GM makes up the information).' },
      { name: 'Courageous Advance', action: '1', level: 4, reqSubclass: 'warrior', desc: 'With a rousing call, you exhort an ally to advance. If your next action is to cast the courageous anthem composition cantrip, one ally of your choice who gains a status bonus from the spell can immediately use their reaction to Stride.' },
      { name: 'In Tune', action: '1', level: 4, reqSubclass: 'maestro', desc: 'You attune your great skill in performing to another, granting them a small measure of your skill as though anyone could do it. If your next action is casting a composition spell with an emanation area, its area spreads from a willing ally of your choice within 60 feet instead of you.\nIf you have Directed Audience, you can have that cone originate from the ally instead.' },
      { name: 'Melodious Spell', action: '1', level: 4, desc: 'You subtly weave your spellcasting into a performance. If the next action you use is to Cast a Spell, the spell gains the subtle trait, hiding the shining runes, sparks of magic, and other manifestations that would usually give away your spellcasting. The trait hides only the spell’s spellcasting actions and manifestations, not its effects, so an observer might still see a ray streak out from you or see you vanish into thin air.\nAs part of using Melodious Spell, you can choose to Create a Diversion, Demoralize, Perform, or Request. If you do so, the spell you cast must have the auditory, emotion, sonic, or visual trait to gain the subtle trait.' },
      { name: 'Rallying Anthem', level: 4, desc: 'You learn the rallying anthem composition cantrip, which protects you and allies.' },
      { name: 'Ritual Researcher', level: 4, reqSubclass: 'enigma', reqSkills: [{ skill: 'occultism', rank: 2 }], desc: 'Careful research into the art of rituals has made you better at performing them. You gain a +2 circumstance bonus to all primary and secondary checks you attempt as part of casting a ritual.' },
      { name: 'Triple Time', level: 4, desc: 'You learn the triple time composition cantrip, which speeds up you and your allies for a round.' },
      { name: 'Versatile Signature', level: 4, reqSubclass: 'polymath', desc: 'While most bards are known for certain signature performances and spells, you’re always tweaking your available repertoire. When you make your daily preparations, you can change one of your signature spells to a different spell of that rank from your repertoire.' },
      { name: 'Assured Knowledge', level: 6, reqSubclass: 'enigma', desc: 'You can procure information with confidence. Whenever you Recall Knowledge using any skill (including Bardic Lore), you can forgo rolling your check to instead receive a result of 10 + your proficiency bonus (don’t apply any other bonuses, penalties, or modifiers).\nAs long as you are an expert in a skill, you meet the prerequisites for the Automatic Knowledge skill feat for that skill, even if you don’t have the Assurance feat for that skill.' },
      { name: 'Defensive Coordination', action: '1', level: 6, reqSubclass: 'warrior', reqFeats: ['Rallying Anthem'], desc: 'Like the storied heroes who persist in the face of overwhelming odds, you and your allies will hold the line. If your next action is to cast the rallying anthem composition cantrip, you can Raise a Shield, and one ally of your choice who gains a status bonus from the spell can immediately use their reaction to Raise a Shield.' },
      { name: 'Dirge of Doom', level: 6, desc: 'You learn the dirge of doom composition cantrip, which frightens your enemies and keeps them from fully recovering from their fear.' },
      { name: 'Educate Allies', level: 6, reqFeats: ['Well-Versed'], action: 'R', desc: 'Trigger - An ally benefiting from one of your composition spells is subject to an effect with the auditory, illusion, linguistic, sonic, or visual trait\nYou tweak the properties of your composition spell to convey a bit of your defensive knowledge. All allies affected by your composition spell gain your +1 circumstance bonus from Well-Versed until the start of your next turn. Teaching your allies also bolsters your own skills; your personal circumstance bonus from Well-Versed also increases to +2 until the start of your next turn.' },
      { name: 'Harmonize', action: '1', level: 6, reqSubclass: 'maestro', desc: 'You can perform multiple compositions simultaneously, typically by performing in multiple ways at the same time, using special vocal techniques to double your voice, or creating occult magic that replicates your song or speech. If your next action is to cast a composition, it becomes a harmonized composition. Unlike a normal composition, a harmonized composition doesn’t end if you cast another composition, and you can cast another composition on the same turn as a harmonized one. Casting another harmonized composition ends any harmonized composition you already have in effect.' },
      { name: 'Song of Marching', level: 6, desc: 'You learn the song of marching composition cantrip, which enables you and your allies to cross vast distances without strain.' },
      { name: 'Steady Spellcasting', level: 6, desc: 'You don’t lose spells easily. If a reaction would disrupt your spellcasting action, attempt a DC 15 flat check. If you succeed, your action isn’t disrupted.' },
      { name: 'Accompany', action: 'R', level: 8, desc: 'Trigger - An ally within 30 feet Casts a Spell\nYou use your performance to supplement an ally’s spellcasting, providing magical energy for their spell in their stead. Attempt a Performance check, using a very high DC for the ally’s level (GM Core 53), and either spend a Focus Point (if the triggering spell is a focus spell) or expend a spell slot at least 1 rank higher than the triggering spell. If you succeed at your Performance check, your ally’s spell doesn’t cost the Focus Point or spell slot that ally would normally need to spend.' },
      { name: 'Call and Response', action: '1', level: 8, desc: 'Your composition takes the form of a call-and-response chant that lets your allies continue the effect without you. If your next action is to cast a composition cantrip with a duration of 1 round, it becomes a call. While the spell is active, one ally of your choice affected by the spell can respond to your call as a single action that has the auditory and concentrate traits to extend the spell’s duration by 1 round. Only one ally can respond to a given call, and responding to the ally’s response has no additional effect' },
      { name: 'Eclectic Skill', level: 8, reqSubclass: 'polymath', reqSkills: [{ skill: 'occultism', rank: 3 }], desc: 'Your broad experiences translate to a range of skills. Your proficiency bonus to untrained skill checks is equal to your level. You can attempt any skill check that normally requires you to be trained, even if you are untrained. If you have legendary proficiency in Occultism, you can attempt any skill check that normally requires you to have expert proficiency, even if untrained or trained.' },
      { name: 'Fortissimo Composition', level: 8, reqSubclass: 'maestro', desc: 'Your anthems grow louder and more potent, bolstered by your muse’s power. You learn the fortissimo composition spellshape focus spell.' },
      { name: 'Know-It-All', level: 8, reqSubclass: 'enigma', desc: 'When you succeed at a check to Recall Knowledge, you gain additional information or context. When you critically succeed at a check to Recall Knowledge, you get additional information or context or can ask an additional follow-up question (the GM chooses which).' },
      { name: 'Reflexive Courage', level: 8, reqSubclass: 'warrior', action: 'R', desc: 'Trigger - A creature within your reach uses an auditory effect, manipulate action, or move action; makes a ranged attack; or leaves a square during its move action\nRequirements - You are affected by courageous anthem\nYou bellow a ferocious call to arms, inspiring yourself to lash out at a foe. Make a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the action is disrupted.' },
      { name: 'Soulsight', level: 8, desc: 'Your muse has opened your senses to the world beyond. You gain spiritsense as an imprecise sense with a range of 60 feet. Spiritsense enables you to sense the spirits of creatures, including living creatures, most non-mindless undead, and haunts within the listed range. As with your hearing and other imprecise senses, you still need to Seek to locate an undetected creature.\nAs spiritsense detects spiritual essence, not physical bodies, it can detect spirits projected by spells such as project image or possessing otherwise soulless objects. It can’t detect soulless bodies, constructs, or objects, and like most senses, it doesn’t penetrate through solid objects.' },
    ] },
  { key: 'champion', name: 'Champion', book: 'player-core', hp: 10, keyAbility: ['str'], hidden: true,
    saves: { fort: 2, ref: 1, will: 2 }, perception: 1, classDC: 1,
    skillsTrainedCount: 3, weapons: 'Trained in simple and martial weapons.', armor: 'Trained in light, medium, and heavy armor, and unarmored defense.',
    proficiencies: { perception: 'Trained', saves: { fort: 'Expert', ref: 'Trained', will: 'Expert' }, skills: ['Trained in Religion', 'Trained in a number of additional skills equal to 3 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in martial weapons', 'Trained in unarmed attacks'], defenses: ['Trained in light armor', 'Trained in medium armor', 'Trained in heavy armor', 'Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: { tradition: 'Divine', keyAbility: 'cha', type: 'devotion' },
    features: [{ name: "Deity and Cause", desc: "Choose a deity and a cause, shaping your champion’s alignment and reaction." }, { name: "Champion's Reaction", desc: "Use your cause’s unique reaction to protect or punish those who threaten your allies." }, { name: "Devotion Spells", desc: "Cast devotion spells, unique focus spells fueled by your faith." }],
    feats: [{ name: "Ranged Reprisal", desc: 'You can use Retributive Strike at greater distance. You can use a ranged weapon to make a ranged Strike instead of a melee Strike for Retributive Strike. The enemy needs to be in range, but not in reach, and it must still be in your champion’s aura. You can also make melee Strikes against enemies a bit farther away. If the enemy that triggered your reaction is outside your reach but is within 5 feet of your reach, as part of your reaction you can Step to put the enemy in your reach before making a melee Retributive Strike.' }, { name: 'Unimpeded Step', desc: 'With a burst of divine liberation, your ally’s movement from your Liberating Step is unaffected by difficult terrain, greater difficult terrain, narrow surfaces, and uneven ground. If you have the exalted reaction benefit, this applies to everyone who Steps.' }] },
  { key: 'monk', name: 'Monk', book: 'player-core', hp: 10, keyAbility: ['str', 'dex'], hidden: true,
    saves: { fort: 2, ref: 2, will: 2 }, perception: 2, classDC: 1,
    skillsTrainedCount: 4, weapons: 'Expert in unarmed attacks; trained in simple weapons.', armor: 'Trained in unarmored defense.',
    proficiencies: { perception: 'Expert', saves: { fort: 'Expert', ref: 'Expert', will: 'Expert' }, skills: ['Trained in your choice of Acrobatics or Athletics', 'Trained in a number of additional skills equal to 4 plus your Intelligence modifier'], attacks: ['Expert in unarmed attacks', 'Trained in simple weapons'], defenses: ['Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: null, features: [{ name: "Flurry of Blows", desc: "Make two unarmed Strikes as a single action." }, { name: "Powerful Fist", desc: "Your fists deal lethal damage and count as unarmed attacks that deal 1d6 bludgeoning." }],
    feats: [{ name: 'Crane Stance', desc: 'Requirements - You are unarmored.\nYour arms flutter like a crane’s wings. You gain a +1 circumstance bonus to AC, but the only Strikes you can make are crane wing attacks. These deal 1d6 bludgeoning damage; are in the brawling group; and have the agile, finesse, nonlethal, and unarmed traits.\nWhile in Crane Stance, reduce the DC for High Jump and Long Jump by 5, and when you Leap, you can move an additional 5 feet horizontally or 2 feet vertically.', action: '1' }, { name: 'Ki Rush', desc: 'You have cultivated your qi to produce magical effects. You gain inner upheaval, qi rush, or another 1st-rank monk qi spell you have access to.\nSpecial - You can select this feat more than once, choosing a different spell each time.' }] },
  { key: 'sorcerer', name: 'Sorcerer', book: 'player-core', hp: 6, keyAbility: ['cha'], hidden: true,
    saves: { fort: 1, ref: 1, will: 2 }, perception: 1, classDC: 1,
    skillsTrainedCount: 3, weapons: 'Trained in simple weapons.', armor: 'Trained in unarmored defense.',
    proficiencies: { perception: 'Trained', saves: { fort: 'Trained', ref: 'Trained', will: 'Expert' }, skills: ['Trained in a number of additional skills equal to 3 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in unarmed attacks'], defenses: ['Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: { tradition: 'Varies by bloodline', keyAbility: 'cha', type: 'spontaneous' },
    features: [{ name: "Bloodline", desc: "Choose a sorcerous bloodline that grants a bonus spell, a bloodline spell, and other benefits." }, { name: "Bloodline Spells", desc: "Gain unique focus spells granted by your sorcerous bloodline." }],
    feats: [{ name: 'Counterspell', desc: 'Trigger - A creature Casts a Spell that you have prepared\nWhen a foe Casts a Spell and you can see its manifestations, you can use your magic to disrupt it. You expend a prepared spell to counter the triggering creature’s casting of that same spell. You lose your spell slot as if you had cast the triggering spell. You then attempt to counteract the triggering spell.\nSpecial - This feat has the trait corresponding to the tradition of spells you cast (arcane, divine, primal, or occult).', action: 'R' }, { name: 'Familiar', desc: 'You make a pact with a creature that serves you and assists your spellcasting. You gain a familiar.' }] },
  { key: 'druid', name: 'Druid', desc: 'The power of nature is impossible to resist. It can bring ruin to the stoutest fortress in minutes, reducing even the mightiest works to rubble, burning them to ash, burying them beneath an avalanche of snow, or drowning them beneath the waves. It can provide endless bounty and breathtaking splendor to those who respect it—and an agonizing death to those who take it too lightly. You are one of those who hear nature’s call. You stand in awe of the majesty of its power and give yourself over to its service.', book: 'player-core', hp: 8, keyAbility: ['wis'],
    saves: { fort: 1, ref: 1, will: 2 }, perception: 1, classDC: 1,
    skillsTrainedCount: 2, weapons: 'Trained in simple weapons.', armor: 'Trained in light and medium armor.',
    proficiencies: { perception: 'Trained', saves: { fort: 'Trained', ref: 'Trained', will: 'Expert' }, skills: ['Trained in Nature', 'Trained in one skill determined by your druidic order', 'Trained in a number of additional skills equal to 2 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in unarmed attacks'], defenses: ['Trained in light armor', 'Trained in medium armor', 'Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: { tradition: 'Primal', keyAbility: 'wis', type: 'prepared' },
    subclassLabel: 'Order',
    subclasses: [
      { key: 'animal', name: 'Animal', desc: 'A strong connection to beasts. Trained in Athletics; grants Animal Companion.' },
      { key: 'leaf', name: 'Leaf', desc: 'Revere the bounty of nature. Trained in Diplomacy; grants Leshy Familiar.' },
      { key: 'storm', name: 'Storm', desc: 'Carry the fury of the storm. Trained in Acrobatics; grants Storm Born.' },
      { key: 'untamed', name: 'Untamed', desc: 'Wear the form of an untamed creature. Trained in Intimidation; grants the Untamed Form focus spell.' },
    ],
    features: [{ name: "Anathema", desc: "Acting against your deity’s edicts can cost you your divine powers." }, { name: "Order", desc: "Choose a druidic order that grants an order spell and additional training." }, { name: "Wild Empathy", desc: "Use Diplomacy to improve the attitude of an animal instead of a person." }],
    feats: [
      { name: 'Animal Companion', level: 1, reqSubclass: 'animal', desc: 'You gain the service of a young animal companion that travels with you on your adventures and obeys any simple commands you give it to the best of its abilities. See Animal Companions for more information.\nRanger - When you Hunt Prey, your animal companion gains the action’s benefits and your hunter’s edge benefit if you have one.' },
      { name: 'Animal Empathy', level: 1, desc: 'You have a connection to the creatures of the natural world that allows you to communicate with them on a rudimentary level. You can ask questions of, receive answers from, and use the Diplomacy skill with animals. In most cases, wild animals will give you time to make your case.' },
      { name: 'Leshy Familiar', level: 1, reqSubclass: 'leaf', desc: 'You call a minor spirit of nature into a plant body, creating a leshy companion to aid you in your spellcasting. You gain a familiar, which has your choice of either the plant or fungus familiar ability; this doesn’t count against your usual limit of familiar abilities (typically 2). The spirit you call has a more tenuous connection to its plant body than fully independent leshies, so it is Tiny in size like other familiars.' },
      { name: 'Plant Empathy', level: 1, desc: 'You have a connection to flora that allows you to communicate with them on a rudimentary level. You can ask questions of, receive answers from, and use the Diplomacy skill with plants and fungus.' },
      { name: 'Reach Spell', action: '1', level: 1, desc: 'You can extend your spells’ range. If the next action you use is to Cast a Spell that has a range, increase that spell’s range by 30 feet. As is standard for increasing spell ranges, if the spell normally has a range of touch, you extend its range to 30 feet.' },
      { name: 'Storm Born', level: 1, reqSubclass: 'storm', desc: 'You are at home out in the elements, reveling in the power of nature unleashed. You do not take circumstance penalties to ranged spell attacks or Perception checks caused by weather, and your targeted spells don’t require a flat check to succeed against a target concealed by weather (such as fog).' },
      { name: 'Verdant Weapon', level: 1, desc: 'You cultivate a seed that can sprout into a wooden staff, vine whip, or another weapon. You spend 10 minutes focusing primal energy into a seed, imprinting it with the potential of a single level 0 weapon you are trained with and that has no mechanical parts or metal components. When holding the imprinted seed, you can use an Interact action to cause it to immediately grow into that weapon; a second Interact action returns it to seed form. The verdant weapon can be etched with runes or affixed with talismans as normal, which are suppressed when the weapon is in seed form.\nYou can have only one verdant seed at a time. If you prepare a second, your first verdant seed immediately becomes a mundane seed; any runes on the previous seed transfer to the new seed at no cost, but inapplicable runes are suppressed.' },
      { name: 'Call of the Wild', level: 2, desc: 'You call upon the creatures of nature to come to your aid. You can spend 10 minutes in concert with nature to replace a spell you’ve prepared in one of your druid spell slots with a summon animal or summon plant or fungus spell of the same rank.' },
      { name: 'Enhanced Familiar', level: 2, desc: 'You infuse your familiar with additional primal energy, increasing its abilities. You can select four familiar or master abilities each day, instead of two.\nSpecial - [Witch] Add the bonus familiar abilities you gain for being a witch to this amount. [Wizard] If your arcane thesis is improved familiar attunement, your familiar’s base number of familiar abilities, before adding any extra abilities from the arcane thesis, is four.' },
      { name: 'Order Explorer', level: 2, desc: 'You have learned the secrets of another druidic order, passing whatever rites of initiation that order requires and gaining access to its secrets. Choose an order other than your own. You gain a 1st-level feat that lists that order as a prerequisite, and you are now a member of that order for the purpose of meeting feat prerequisites. If you commit acts anathema to your new order, you lose all feats and abilities requiring that order but retain your other druid feats and abilities. You don’t gain any of the other benefits of the order you chose.\nSpecial - You can take this feat multiple times. Each time you do, you must choose a different order other than your own.', grantsFeat: { pool: 'class-other-subclass' } },
      { name: 'Poison Resistance', level: 2, desc: 'Your affinity for the natural world grants you protection against some of its dangers. You gain poison resistance equal to half your level, and you gain a +1 status bonus to saving throws against poisons.' },
      { name: 'Anthropomorphic Shape', level: 4, reqSubclass: 'untamed', desc: 'Humanoids’ supposed place apart from animals is folly—taking on their forms just requires some extra practice. You add the shapes listed in humanoid form to your untamed form list.' },
      { name: 'Elemental Summons', level: 4, desc: 'You can call the elements to you. You can spend 10 minutes in concert with nature to replace a spell you’ve prepared in one of your druid spell slots with a summon elemental spell of the same rank.' },
      { name: 'Forest Passage', level: 4, reqSubclass: 'leaf', desc: 'You can always find a path, almost as if foliage parted before you. You ignore any difficult terrain caused by plants and fungi, such as bushes, vines, and undergrowth.' },
      { name: 'Form Control', action: '1', level: 4, reqSubclass: 'untamed', desc: 'With additional care and effort, you can take on an alternate shape for a longer period of time. If your next action is to cast untamed form, the spell’s rank is 2 lower than normal (minimum 1st rank), but you can remain transformed for up to 1 hour or the listed duration (whichever is longer). You can still Dismiss untamed form as normal.' },
      { name: 'Leshy Familiar Secrets', level: 4, reqSubclass: 'leaf', desc: 'The leaf order’s secrets allow your familiar to take advantage of its leshy form. You can select one additional familiar ability each day, which must be one of the following leshy familiar abilities. You can’t select more than one ability from this feat at a time.\nGrasping Tendrils - Your familiar can extend vines or similar tendrils, increasing its reach to 15 feet.\nPurify Air - Your familiar recycles air, providing enough oxygen for a Medium creature in areas with stale air, such as a sealed chamber or extradimensional space. Creatures within a 15-foot emanation of the leshy gain a +2 circumstance bonus to their saving throws against inhaled poison effects, olfactory effects, or other effects that rely on breathing (such as toxic cloud), at the GM’s discretion.\nVerdant Burst - When your familiar dies, it releases its primal energy to cast the 3-action version of heal, heightened to a rank 1 lower than your highest-rank spell slot. The heal spell gains a status bonus equal to twice the spell’s rank to the Hit Points it restores to plants. You must be able to cast 2nd-rank spells using spell slots to select this familiar ability.' },
      { name: 'Mature Animal Companion', level: 4, reqFeats: ['Animal Companion'], desc: 'Your animal companion has grown up over the course of your adventures, becoming a mature animal companion and gaining additional capabilities.\nYour animal companion has greater independence. During an encounter, even if you don’t use the Command an Animal action, your animal companion can still use 1 action that round on your turn to Strike or Stride (or Burrow, Climb, Fly, or Swim if it has that Speed). It can do this at any point during your turn, as long as you aren’t currently taking an action. If it does, that’s all the actions it gets that round—you can’t Command it later.' },
      { name: 'Order Magic', level: 4, reqFeats: ['Order Explorer'], desc: 'You have delved deeper into the teaching of a new order, gaining access to a coveted order spell. Choose an order you have selected with Order Explorer. You gain the initial order spell from that order.\nSpecial - You can take this feat multiple times. Each time you do, you must choose a different order you have selected with Order Explorer.' },
      { name: 'Snowdrift Spell', action: '1', level: 4, reqSubclass: 'storm', desc: 'The howling wind and precipitation of your magic turn to thick snow. If your next action is to Cast a Spell that has the air, water, or cold trait, and that does not have the fire trait, select one creature affected by the spell on the ground. Each square on the ground under or adjacent to the creature fills with ankle-deep snow. Those squares are difficult terrain until the beginning of your next turn. A creature can Interact to clear a square of snow, and the snow in a square melts if that square is exposed to a fire effect.' },
      { name: 'Current Spell', action: '1', level: 6, desc: 'As you use your magic to manipulate air or water, you spin off some of its currents to form a barrier around you. If your next action is to Cast a Spell with the air or water trait, until the start of your next turn, you gain a +1 circumstance bonus to AC or a +2 circumstance bonus against ranged attacks. This effect has the air or water trait, or both, depending on the traits of the spell you cast. You also gain a +1 circumstance bonus to all saves against effects with the air trait, water trait, or both until the start of your next turn, depending on the spell’s traits.' },
      { name: 'Grown of Oak', level: 6, reqSubclass: 'leaf', desc: 'You can make your skin take on the woody endurance of an ancient tree and have your familiar follow suit. You can cast oaken resilience at will as an innate primal spell with a spell rank one lower than the highest rank of spells you can cast. This spell targets you, as well as your leshy familiar if it’s within 30 feet of you.' },
      { name: 'Insect Shape', level: 6, reqSubclass: 'untamed', desc: 'Your understanding of life expands, allowing you to mimic a wider range of creatures. Add the shapes in insect form to your untamed form list. Whenever you use untamed form to polymorph into the non-flying insect shapes listed in pest form, the duration is 24 hours instead of 10 minutes.' },
      { name: 'Instinctive Support', action: 'F', level: 6, reqFeats: ['Animal Companion'], desc: 'Trigger - You Cast a non-cantrip spell that targets only your animal companion\nWhen you support your animal companion, your companion supports you in turn. After your spell takes place, your companion gains its actions for the turn, as if you Commanded it, and one of the actions must be Support. If the companion has used any other actions already, it can’t Support you, as normal.' },
      { name: 'Steady Spellcasting', level: 6, desc: 'You don’t lose spells easily. If a reaction would disrupt your spellcasting action, attempt a DC 15 flat check. If you succeed, your action isn’t disrupted.' },
      { name: 'Storm Retribution', level: 6, reqSubclass: 'storm', action: 'R', desc: 'Trigger - An opponent adjacent to you critically hits you with a melee weapon or melee unarmed attack\nRequirements - You have at least 1 available Focus Point\nYou lash out, directing a burst of storming fury toward a creature that has harmed you. You cast tempest surge on the triggering opponent and push that creature, moving it 5 feet away from you if it fails its Reflex save, or 10 feet if it critically fails. This movement is forced movement.' },
      { name: 'Deimatic Display', action: '1', level: 8, desc: 'Imitating animal threat displays, you make yourself appear larger and more imposing. Attempt an Intimidation check to Demoralize each enemy within 30 feet. This attempt has the visual trait, loses the auditory trait, and you don’t take a penalty if the creature doesn’t understand your language. Roll your check only once and compare it to the Will DC of each target. You gain a +2 circumstance bonus to the check against animal, fungus, and plant creatures and take a –2 circumstance penalty against other creatures. Each target is then temporarily immune for 1 minute.' },
      { name: 'Ferocious Shape', level: 8, reqSubclass: 'untamed', desc: 'You’ve mastered the shape of dinosaurs. Add the shapes listed in dinosaur form to your untamed form list. Whenever you use untamed form to take a shape that grants you a specific Athletics modifier, you gain a +1 status bonus to your Athletics checks.' },
      { name: 'Fey Caller', level: 8, desc: 'You have learned some of the tricks the fey use to bend primal magic toward illusions and trickery. Add illusory disguise, illusory object, and illusory scene to your spell list, which you cast as primal spells.' },
      { name: 'Floral Restoration', action: '1', level: 8, reqSubclass: 'leaf', desc: 'Frequency - once per day\nYou request that nearby plants share their vitality with you to replenish your body and magic. You regain 1 Focus Point and 4d8 Hit Points.\nYou must be in a location of at least 15 feet by 15 feet of healthy plant life, though this can be grass, lichen, seaweed, or any other form of naturally occurring flora. Using Floral Restoration on a given section of nature does not harm it, but it prevents that section of nature from giving its vitality to another use of Floral Restoration for 24 hours.\nAt 9th level, and every 2 levels thereafter, increase the healing by 1d8.' },
      { name: 'Incredible Companion', level: 8, reqFeats: ['Mature Animal Companion'], desc: 'Your animal companion continues to grow and develop. It becomes either a nimble or savage animal companion, gaining additional capabilities determined by the type.' },
      { name: 'Raise Menhir', action: '2', level: 8, desc: 'Frequency - once per hour\nYou raise a druidic monument, such as a standing stone or warding tree, from the ground, creating a powerful primal ward that blocks other types of magic. The monument appears in an unoccupied square on the ground within 30 feet, making that square difficult terrain. Choose arcane, divine, or occult; all creatures within 15 feet of the monument gain a +2 status bonus to their saving throws against effects with that trait. The monument lasts for 1 round before crumbling back into the earth or wilting away into nothingness, but you can Sustain the monument for up to 1 minute.' },
      { name: 'Soaring Shape', level: 8, reqSubclass: 'untamed', desc: 'Wings free you from the shackles of the ground below. Add the bat and bird shapes in aerial form to your untamed form list. If you have Insect Shape, you also add the wasp shape to your untamed form list. If you have Ferocious Shape, you also add the pterosaur shape to your untamed form list. Whenever you use untamed form to take a shape that grants you a specific Acrobatics modifier, you gain a +1 status bonus to Acrobatics checks.' },
    ] },
  { key: 'alchemist', name: 'Alchemist', desc: 'There’s no sight more beautiful to you than a strange brew bubbling in a beaker, and you consume your ingenious elixirs with abandon. You’re fascinated by uncovering the secrets of science and the natural world, and you’re constantly experimenting in your lab or on the go with inventive concoctions for every eventuality. You are fearless in the face of risk, hurling explosive or toxic creations at your foes. Your unique path toward greatness is lined with alchemical brews that push your mind and body to their limits.', book: 'player-core-2', hp: 8, keyAbility: ['int'],
    saves: { fort: 2, ref: 2, will: 1 }, perception: 1, classDC: 1,
    skillsTrainedCount: 3, weapons: 'Trained in simple weapons plus alchemical bombs.', armor: 'Trained in light and medium armor.',
    fixedSkills: ['crafting'],
    proficiencies: { perception: 'Trained', saves: { fort: 'Expert', ref: 'Expert', will: 'Trained' }, skills: ['Trained in Crafting', 'Trained in a number of additional skills equal to 3 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in alchemical bombs', 'Trained in unarmed attacks'], defenses: ['Trained in light armor', 'Trained in medium armor', 'Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: null,
    subclassLabel: 'Research Field',
    subclasses: [
      { key: 'bomber', name: 'Bomber', desc: 'You specialize in explosions and other violent reactions. Gain two common 1st-level alchemical bomb formulas. When throwing a splash bomb, you can deal splash damage to only the primary target instead of the usual area, and your versatile vials can deal cold, electricity, or fire damage instead of acid. At 5th level, you can cause a splash bomb to deal splash damage equal to your Intelligence modifier. At 13th level, your bombs’ splash can reach 10 feet (15 feet with Expanded Splash).', grantsFeat: { pool: 'fixed', options: ['Quick Bomber'] } },
      { key: 'chirurgeon', name: 'Chirurgeon', desc: 'You concentrate on healing others with alchemy. Gain two common 1st-level healing elixir formulas, and use your Crafting modifier in place of Medicine for all Medicine checks and prerequisites. Your versatile vials can be drunk or thrown at a willing creature to heal it instead of dealing damage. At 5th level, a creature that drinks one of your infused healing elixirs also gains temporary HP equal to your Intelligence modifier. At 13th level, Quick Alchemy elixirs of life heal their maximum possible HP instead of rolling.', grantsFeat: { pool: 'fixed', options: ['Soothing Vials'] } },
      { key: 'mutagenist', name: 'Mutagenist', desc: 'You focus on bizarre mutagenic transformations that trade one aspect of your being to strengthen another. Gain two common 1st-level mutagen formulas. Drinking a mutagen grants temporary HP equal to your Intelligence modifier plus half your level, and a versatile vial can suppress one of your mutagens’ drawbacks until the start of your next turn. At 5th level, you can end a mutagen to reroll a failed Fortitude save. At 13th level, you can be under the effects of two mutagens at once, keeping both benefits until a third mutagen forces you to drop one.', grantsFeat: { pool: 'fixed', options: ['Alchemical Familiar'] } },
      { key: 'toxicologist', name: 'Toxicologist', desc: 'You specialize in toxins and venoms of all types. Gain two common 1st-level alchemical poison formulas, and apply injury poisons as a single action instead of a 2-action activity. Your infused poisons deal acid damage instead of poison damage to creatures immune or highly resistant to poison, and your versatile vials gain the poison trait and can be applied as an injury poison. At 5th level, you gain poison resistance equal to half your level. At 13th level, a creature that critically fails its save against one of your infused injury poisons sprays it onto an adjacent creature.', grantsFeat: { pool: 'fixed', options: ['Blowgun Poisoner'] } },
    ],
    features: [
      { name: 'Alchemy', desc: 'Craft alchemical items using normal reagents and the Craft activity, or use an alchemist’s toolkit to create temporary items for free during daily preparations (Advanced Alchemy) or on the fly (Quick Alchemy). You automatically identify any alchemical item you have the formula for.' },
      { name: 'Formula Book', desc: 'Keep formulas for the alchemical items you know how to make. You start with formulas for two common 1st-level alchemical items of your choice, plus those granted by Alchemical Crafting and your research field, and learn two more common formulas of any level each time you gain a level.' },
      { name: 'Versatile Vials', desc: 'During daily preparations, create a number of versatile vials up to 2 plus your Intelligence modifier — fast-acting chemicals usable as bombs, for Quick Alchemy, or per your research field. Regain 2 vials for every 10 minutes spent in exploration mode, up to your maximum.' },
      { name: 'Quick Alchemy', action: '1', desc: 'Expend a versatile vial to create an alchemical consumable of your level or lower from your formula book, potent until the start of your next turn, or create an especially short-lived quick vial usable only as a bomb, potent until the end of your turn.' },
      { name: 'Research Field', desc: 'Choose a field of alchemical research — Bomber, Chirurgeon, Mutagenist, or Toxicologist — granting extra formulas, a field benefit, a special use for your versatile vials, and further discoveries at 5th, 11th, and 13th level.' },
    ],
    feats: [
      { name: 'Alchemical Familiar', level: 1, reqSubclass: 'mutagenist', desc: 'You have used alchemy to create life, a simple creature formed from alchemical materials, reagents, and a bit of your own blood. You gain a familiar, which has the construct familiar ability; this is permanent, doesn’t require the familiar to have the tough familiar ability, and doesn’t count against your usual limit of familiar abilities (typically 2). The familiar uses your Intelligence modifier to determine its Perception, Acrobatics, and Stealth modifiers.' },
      { name: 'Alchemical Assessment', level: 1, reqSkills: [{ skill: 'crafting', rank: 1 }], desc: 'You can identify alchemical items quickly. When using the Crafting skill to Identify Alchemy on an alchemical item you hold, you can do so as a single action, rather than spending 10 minutes.' },
      { name: 'Blowgun Poisoner', level: 1, reqSubclass: 'toxicologist', desc: 'You can capably deliver toxins with a blowgun. Your blowgun Strikes can apply injury poisons even if they deal no damage due to a creature’s resistance. If you critically succeed at a blowgun Strike using a poisoned dart, the target’s initial save against the poison is one degree of success worse than the creature rolls; this is a misfortune effect.\nIn addition, if you make a blowgun Strike while hidden or undetected, you don’t automatically become observed. Instead, immediately attempt a Stealth check against the Perception DC of the target. If you succeed, you don’t become observed, and are hidden (if you were undetected, you still become hidden rather than remaining undetected).' },
      { name: 'Far Lobber', level: 1, desc: 'You’ve learned how to throw a longer distance. When you throw an alchemical bomb, it has a range increment of 30 feet instead of the usual 20 feet.' },
      { name: 'Quick Bomber', action: '1', level: 1, reqSubclass: 'bomber', desc: 'You keep your bombs and bomb-related reagents in easy-to-reach pouches from which you draw without thinking. You Interact to draw a bomb, draw a versatile vial, or use Quick Alchemy to create a bomb, then Strike with the bomb. If you have the ability to create more than one bomb at a time with Quick Alchemy (such as from the double brew class feature), you can Strike with only one of the bombs you create with this action.' },
      { name: 'Soothing Vials', level: 1, reqSubclass: 'chirurgeon', desc: 'The healing chemicals in your versatile vials also help calm a patient’s mind. When a living creature affected by a mental effect regains Hit Points from one of your versatile vials, it can immediately attempt a new Will saving throw to end one mental effect of its choice. It gains a +1 item bonus to the saving throw.' },
      { name: 'Clotting Elixirs', level: 2, desc: 'Your restorative concoctions have a clotting effect on the drinker’s blood. When a living creature drinks an infused elixir with the healing trait that you have created, it can immediately attempt a DC 10 flat check to remove any persistent bleed damage.' },
      { name: 'Smoke Bomb', level: 2, desc: 'You can add a tarry additive to an alchemical bomb to make it emit smoke. When thrown, in addition to its normal effects, the bomb creates a cloud of smoke in a 10-foot burst. You choose which corner of the target’s space (or the space in which the bomb lands) the cloud is centered on. Creatures within that area have the concealed condition, and all other creatures are concealed to them. The smoke lasts for 1 minute or until dissipated by a strong wind.' },
      { name: 'Revivifying Mutagen', action: '1', level: 2, desc: 'Requirements - You are under the effects of a mutagen.\nYou metabolize a mutagen to heal yourself. You regain 1d6 Hit Points for every 2 levels you have, but the mutagen’s duration immediately ends.' },
      { name: 'Pernicious Poison', level: 2, desc: 'You can add a toxic additive to an alchemical poison to make it splash poison on its target. A poison with this additive deals an amount of poison damage equal to the poison’s level if the target succeeds at its initial saving throw against it. A target that critically succeeds at its saving throw against this poison still takes no damage.' },
      { name: 'Improvise Admixture', action: '1', level: 2, desc: 'Frequency - once per day\nRequirements - You have fewer than your maximum number of versatile vials, and you’re either holding or wearing an alchemist’s toolkit.\nYou scrounge together enough ingredients from what’s left in your alchemist’s toolkit to produce a few more versatile vials on the fly. Attempt a Crafting check. The DC is usually a standard-difficulty DC for your level, but the GM can assign a different DC based on the circumstances. The number of vials you regain depends on the result of your check (up to your maximum).\nCritical Success - You regain 3 versatile vials.\nSuccess - You regain 2 versatile vials.\nFailure - You regain 1 versatile vial.\nCritical Failure - You don’t regain any versatile vials.' },
      { name: 'Efficient Alchemy', level: 4, desc: 'Thanks to the time you’ve spent studying and experimenting, you know how to scale your formulas into larger batches that don’t require any additional attention. Increase the number of items you can create each day with advanced alchemy to 6 + your Intelligence modifier.\nIn addition, when you Craft alchemical consumables during downtime, you can produce twice as many alchemical items in a single batch without spending additional preparatory time. For instance, if you are creating elixirs of life, you can craft up to eight elixirs in a single batch using downtime, rather than four. This doesn’t change the amount of alchemical reagents or other ingredients required to craft each item, nor does it change your rate of progress for days past the base downtime spent.' },
      { name: 'Healing Bomb', level: 4, desc: 'You can add a foamy catalyst to an elixir of life to turn it into a topical projectile. You can throw the elixir at a creature within 20 feet as an Interact action to heal that creature and those near it. The target is affected as though it drank the elixir, and each living creature adjacent to it regains HP from the bomb equal to the elixir’s number of damage dice (3 HP for a lesser elixir of life, for example).' },
      { name: 'Invigorating Elixir', level: 4, desc: 'You can mix an aromatic salve into an elixir with the healing trait to soothe physical maladies. In addition to its normal effects, the elixir can be imbibed by a creature prevented from doing so (such as a sickened creature). In addition to its other effects, the elixir attempts to counteract an effect imposing one of the following conditions of the imbiber’s choice: clumsy, enfeebled, sickened, or stupefied. Use half your level rounded up for the counteract rank and your class DC – 10 for the counteract modifier. The imbiber is then temporarily immune to the effects of this additive for 10 minutes. The additive can’t counteract curses, diseases, or conditions that are part of the creature’s normal state.' },
      { name: 'Regurgitate Mutagen', action: '1', level: 4, desc: 'Requirements - You are under the effects of a mutagen.\nYou redirect a mutagen within your body to spit a stream of stomach acid at a foe. A creature within 30 feet takes 1d6 acid damage for every 2 levels you have, with a basic Reflex save against your class DC. On a failure, the creature is also sickened 1 (or sickened 2 on a critical failure). The mutagen’s duration immediately ends.' },
      { name: 'Tenacious Toxins', level: 4, desc: 'Your victims tend to expire long before your poisons, since the latter have been specifically formulated to last longer. The maximum duration of any poison you create increases by an amount equal to the poison’s stage 1 interval, to a maximum of twice the poison’s maximum duration.' },
      { name: 'Debilitating Bomb', level: 6, desc: 'You can add a crystalline additive to an alchemical bomb to have it undermine your enemy. Choose dazzled, deafened, off-guard, or a –5-foot status penalty to Speeds. If the attack with the bomb hits, in addition to the bomb’s normal effects, the target must succeed at a Fortitude saving throw or take that effect until the start of your next turn. Use your class DC for this saving throw, even if someone else throws the bomb.' },
      { name: 'Directional Bombs', level: 6, desc: 'You can lob bombs with great force and a precise trajectory to angle the splash in a cone that sprays in a single direction, potentially allowing you to avoid allies and splash deeper into enemy lines. When throwing an alchemical bomb with the splash trait, instead of splashing all squares adjacent to the target, you can create a splash in a 15-foot cone. You choose the cone’s direction, but its first square must be a square in the target’s space.\nSpecial - If you have the Expanded Splash feat or another ability that increases the radius of splash damage, you can have the splash damage be a 20-foot cone.' },
      { name: 'Combine Elixirs', level: 6, desc: 'You can add the full ingredients of a second elixir to an elixir you make to create a hybrid concoction. You must expend an additional versatile vial to make this combined elixir, and the ingredients must be for an elixir of the same level or lower that you could create with Quick Alchemy. When this combination elixir is consumed, both the constituent elixirs take effect. For example, you can combine two lesser elixirs of life to create a combined elixir that heals twice the normal amount, or you can combine a lesser darkvision elixir with a lesser eagle-eye elixir to both gain darkvision and find secret doors.' },
      { name: 'Sticky Poison', level: 6, desc: 'A combination of additional viscosity and careful application keeps your weapons poisoned even when suffering significant wear and tear. If your Strike with a poisoned weapon would expend its poison without your target attempting an initial save (due to resistance or your Strike being a critical failure, for example), attempt a DC 5 flat check. On a success, your weapon remains poisoned. If your Strike with a poisoned weapon succeeds, attempt a DC 17 flat check. On a success, your weapon remains poisoned until the end of your next turn.' },
      { name: 'Alter Admixture', level: 8, desc: 'Requirements - You are holding or wearing an alchemist’s toolkit.\nSometimes, you need to adapt your alchemical mixtures to new situations. In a process that takes 10 minutes, you change an item you created with advanced alchemy into a similar item. You can change an alchemical bomb into another type of alchemical bomb, an elixir into another type of elixir, or a poison into another type of poison. If it’s unclear whether two alchemical consumables are similar, the GM decides. You must know the formula for the new item, and the new item must be of the same or lower item level than the original item. The new item still keeps the infused trait, and it remains potent as long as the original item would have.' },
      { name: 'Sticky Bomb', level: 8, desc: 'You can mix in a sticky additive to an alchemical bomb to make its contents adhere and continue to deal damage. A creature hit by a sticky bomb also takes persistent damage equal to and of the same type as the bomb’s splash damage. If the bomb already deals persistent damage, combine the two amounts. Use the splash damage amount listed in the bomb’s stat block, even if you used an ability to change the splash damage dealt.' },
      { name: 'Improved Invigorating Elixir', level: 8, reqFeats: ['Invigorating Elixir'], desc: 'Choose physical invigoration or mental invigoration, and add the listed conditions to those you can choose for an invigorating elixir you create to counteract: Physical Invigoration blinded, deafened, drained, paralyzed, slowed; Mental Invigoration confused, controlled, fleeing, frightened, paralyzed, slowed.\nSpecial - You can select this feat a second time to choose a different type of invigoration and add its options to those you can choose.' },
      { name: 'Mutant Physique', level: 8, desc: 'Basic mutagens that affect your physical form can bring out the beast within you, turn you nigh invincible, or make your body more elastic. While you’re affected by one of the listed mutagens, you get an additional benefit.\nBestial Mutagen - You gain the mutagen’s item bonus to your Intimidation checks. In addition, you increase the damage die size of your claws and jaws by one step, and they gain the deadly d10 trait.\nJuggernaut Mutagen - You gain resistance to all physical damage equal to half your level.\nQuicksilver Mutagen - You can stretch your legs and Step up to 10 feet, and you can squish and compress your body, allowing you to make it through tight spaces as if you were one size smaller, in addition to any effect from Squeezing.\nSpecial - If you can be under the effects of multiple mutagens (with the mutagenist greater field discovery, for example), you get all relevant benefits.' },
      { name: 'Pinpoint Poisoner', level: 8, desc: 'Unsuspecting targets are especially vulnerable to your poisons. When you successfully Strike an off-guard creature with a poisoned weapon or expose an off-guard creature to an inhaled poison, that creature takes a –2 circumstance penalty to its initial save against that poison.' },
      { name: 'Expanded Splash', level: 10, desc: 'You can throw bombs at just the right trajectory to create especially large and powerful explosions. When you throw an alchemical bomb and that bomb has the splash trait, you can have the splash damage affect all creatures within 10 feet of the target instead of 5 feet. If you do, you gain a status bonus to the bomb’s splash damage equal to your Intelligence modifier. If you have the bomber 5th-level field discovery, this additional damage applies even if you caused your bomb to deal splash damage equal to your Intelligence modifier instead of the normal amount, allowing your bombs to deal splash damage equal to double your Intelligence modifier.' },
      { name: 'Advanced Efficient Alchemy', level: 10, reqFeats: ['Efficient Alchemy'], desc: 'You make an even-larger batch of alchemical items each morning. Increase the maximum number of items you can create with advanced alchemy to 8 + your Intelligence modifier, or to 10 + your Intelligence modifier if you’re 16th level or higher.' },
      { name: 'Unstable Concoction', level: 10, desc: 'You can mix a wondrous yet volatile liquid into an alchemical consumable if it has an initial effect that uses dice. You increase the size of any dice for the item’s initial effect by one step. For instance, you could increase damage from a moderate alchemist’s fire to 2d10 or healing from a moderate elixir of life to 5d8+12. Because this affects only initial dice, it wouldn’t increase unarmed attack damage from a bestial mutagen, persistent damage from an acid flask, and the like. When this item is activated, the creature activating it must succeed at a DC 10 flat check or take acid damage equal to the item’s level.' },
      { name: 'Greater Debilitating Bomb', level: 10, reqFeats: ['Debilitating Bomb'], desc: 'You have learned enhanced techniques and alchemical secrets that allow you to expand the range of effects you can impose with your bombs. When you use Debilitating Bomb, add the following to the list you can choose from: clumsy 1, enfeebled 1, stupefied 1, or –10-foot status penalty to Speeds.' },
      { name: 'Extend Elixir', level: 12, desc: 'Integrating your own personal energy into the elixirs you create causes them to affect you for longer. When you consume one of your alchemical items that has the elixir and infused traits and a duration of 1 minute or longer, that elixir’s duration is doubled. If you created the item with Quick Alchemy, this can’t cause it to exceed the 10-minute duration limit.' },
      { name: 'Uncanny Bombs', level: 12, reqFeats: ['Far Lobber'], desc: 'You lob bombs unerringly, despite obstructions or distance. When you throw an alchemical item with the bomb trait, its range increment increases to 60 feet, you reduce any circumstance bonus to the target’s AC from cover by 1, and you automatically succeed at the flat check when targeting a concealed creature.' },
      { name: 'Supreme Invigorating Elixir', level: 12, reqFeats: ['Invigorating Elixir'], desc: 'For the purposes of counteracting effects with invigorating elixirs, treat your level as though it were 2 higher. Add the listed conditions to those you can choose for an invigorating elixir you create to counteract: petrified, stunned. You can also choose a disease regardless of what, if any, conditions it imposes.' },
      { name: 'Double Poison', level: 14, desc: 'You can apply two different infused injury poisons to the same weapon, though not to a piece of ammunition. Each poison’s level must be 2 or more levels lower than your level. You have to apply the two poisons individually. Once you’ve applied both, the poisons merge into a double poison that uses the lower of the two poisons’ DCs and number of stages. This double poison is virulent only if both poisons were virulent. If the poisons require different types of saving throws (such as Fortitude and Will), choose which of them the double poison uses. Combine the effects of each stage of the poison on any creature affected by it. For each stage of the poison, use the effects of both poisons and the longer interval for that stage among the two poisons.' },
      { name: 'Mutant Innervation', level: 14, desc: 'Basic mutagens that affect your mind and thoughts can make you communicate telepathically, protect you from being detected, or let you communicate with anyone. While you’re affected by one of the listed mutagens, you get an additional benefit.\nCognitive Mutagen - You also gain the mutagen’s item bonus to Deception, Diplomacy, Intimidation, Medicine, Nature, Performance, Religion, and Survival checks. In addition, you can communicate telepathically with creatures within 60 feet with whom you share a language. The communication is two-way once you establish it, so a creature you contact can also communicate with you.\nSerene Mutagen - Detection, revelation, and scrying effects of 9th rank (or 17th level) or lower detect nothing from you or your possessions and auras. For instance, detect magic would still detect other magic in the area, but not any magic on you.\nSilvertongue Mutagen - Ignore circumstance penalties you would take to Deception, Diplomacy, Intimidation, and Performance checks. In addition, your words transcend linguistic barriers; everyone listening to you speak hears your words as if you were speaking in their own language (though you don’t actually speak that language, nor does this ability allow you to understand any additional languages).\nSpecial - If you can be under the effects of multiple mutagens (with the mutagenist greater field discovery, for example), you get all relevant benefits.' },
      { name: 'True Debilitating Bomb', level: 14, reqFeats: ['Greater Debilitating Bomb'], desc: 'You have discovered increasingly devastating ways for your bombs to impede your foes. When you use Debilitating Bomb, add the following to the list of effects you can choose from: enfeebled 2, stupefied 2, or a –15-foot status penalty to Speeds.' },
      { name: 'Eternal Elixir', level: 16, reqFeats: ['Extend Elixir'], desc: 'Your body readily accepts and retains minor changes. When you drink one of your alchemical items that has the elixir and infused traits and a duration of 1 minute or more, you can make the elixir’s duration indefinite. This can exceed the 10-minute limit of an item made with Quick Alchemy. You can do so only if the elixir’s level is half your level or lower. If you later consume a different elixir and make it indefinite, the effect of the previous indefinite elixir ends.' },
      { name: 'Exploitive Bomb', level: 16, desc: 'You can mix a refractile substance into an alchemical bomb to foil resistances. Choose one damage type the bomb can deal. Any damage dealt by the bomb—including initial, splash, and persistent damage —ignores an amount of that resistance equal to your level.' },
      { name: 'Persistent Mutagen', level: 16, reqFeats: ['Extend Elixir'], desc: 'You’ve trained your physical form to remain stable. Once per day, when you consume an alchemical item with the infused and mutagen traits, you can extend its duration to last until the next time you make your daily preparations instead of its normal duration. Unlike with the normal extension from Extend Elixir, this can exceed the duration of an item created with Quick Alchemy beyond its normal 10-minute limit.' },
      { name: 'Improbable Elixirs', level: 18, desc: 'Your mastery of alchemical secrets enables you to replicate effects most believe can be achieved only via magic. Select a number of potions equal to your Intelligence modifier (minimum 1); these potions must be of 9th level or lower. You gain formulas to create these potions as alchemical consumables with the elixir trait. When making these alchemical elixirs, you can substitute alchemical reagents for an equal value of magical components, and you can use an alchemist’s toolkit (for Quick Alchemy) or an alchemist’s lab (for the Craft activity) instead of any other required toolkits. Other than that, the formula doesn’t change. Once you’ve chosen the potion formulas, they can’t be changed.' },
      { name: 'Miracle Worker', level: 18, desc: 'Frequency - once every 10 minutes\nYour alchemical mastery can resuscitate the recently slain. You can administer a major or true elixir of life to a creature who has been dead for no more than 2 rounds. When you do, that creature is immediately returned to life with 1 Hit Point and becomes wounded 1.' },
      { name: 'Perfect Debilitation', level: 18, reqFeats: ['Debilitating Bomb'], desc: 'You have perfected the formulas for bombs that impede your enemies. When you use Debilitating Bomb, your target avoids the condition the bomb imposes only if it critically succeeds at its saving throw.' },
      { name: 'Alchemical Revivification', level: 20, desc: 'If you die while under the effect of at least one elixir, the alchemical compounds in your bloodstream bring you back to life at the start of your next turn. You’re affected by an elixir of rejuvenation, then a true elixir of life, then your choice of a major bestial mutagen, major juggernaut mutagen, or major quicksilver mutagen as though you just imbibed it. These automatic reactions don’t get any special benefits you add when creating or using these items. Because you died, all other alchemical compounds in your bloodstream are inert. After being revived, you’re temporarily immune to Alchemical Rejuvenation for 1d4 hours.' },
      { name: 'Craft Philosopher’s Stone', level: 20, desc: 'Your research has paid off, culminating in the legendary philosopher’s stone. You learn the formula for the philosopher’s stone and can add it to your formula book.' },
      { name: 'Mega Bomb', action: '2', level: 20, desc: 'You can add a highly explosive additive to an alchemical bomb to turn it into a mega bomb. Throwing this bomb takes a 2-action activity instead of a Strike. This isn’t a Strike, and you don’t make an attack roll. The mega bomb explodes in a 30-foot burst within 60 feet. It deals damage as if each creature were the primary target, with a basic Reflex save. On a failed save, a creature also takes any extra effects that affect a primary target (such as off-guard from bottled lightning). Though all targets in the area take splash damage as primary targets, there is no further splash beyond that area.' },
    ] },
  { key: 'witch', name: 'Witch', desc: 'You command powerful magic, not through study or devotion, but as an agent for an otherworldly patron that even you don’t entirely understand. This entity might be a covert divinity, a powerful fey, an ancient spirit, or any other mighty supernatural being—but its nature is likely as much a mystery to you as it is to others. Through a special familiar, your patron grants you versatile spells and powerful hexes to use as you see fit, though you’re never certain if you’re merely serving your patron’s larger plan.', book: 'player-core', hp: 6, keyAbility: ['int'],
    saves: { fort: 1, ref: 1, will: 2 }, perception: 1, classDC: 1,
    skillsTrainedCount: 3, weapons: 'Trained in simple weapons.', armor: 'Trained in unarmored defense.',
    proficiencies: { perception: 'Trained', saves: { fort: 'Trained', ref: 'Trained', will: 'Expert' }, skills: ['Trained in one skill determined by your patron', 'Trained in a number of additional skills equal to 3 plus your Intelligence modifier'], attacks: ['Trained in simple weapons', 'Trained in unarmed attacks'], defenses: ['Trained in unarmored defense'], classDC: 'Trained' },
    spellcasting: { tradition: 'Varies by patron', keyAbility: 'int', type: 'prepared' },
    patronRequired: true,
    features: [{ name: "Patron", desc: "Choose an otherworldly patron, determining your spellcasting tradition, a trained skill, your first lesson, and a unique familiar ability." }, { name: "Familiar", desc: "Your patron communes with you through a familiar, the source and repository of the spells you prepare each day." }, { name: "Hexes", desc: "Cast hex focus spells granted by your patron and lessons, though your patron allows only one hex each turn." }],
    feats: [
      { name: 'Cackle', level: 1, action: 'F', desc: 'Your patron’s power fills you with confidence, letting you sustain a magical working even as a quick burst of laughter leaves your lips. You learn the cackle hex.' },
      { name: 'Cauldron', level: 1, desc: 'You can brew magic in your cauldron, creating useful magical concoctions. You can use the Craft activity to create oils and potions. You immediately gain the formulas for four common 1st-level oils or potions. At 4th level and every 2 levels beyond that, you gain the formula for a common oil or potion of that level or lower (a 4th-level potion if you’re 4th level, a 6th-level potion if you’re 6th level, and so on). If you have a familiar, you can have your familiar learn these formulas rather than storing them in a formula book. Your familiar can learn new formulas in the same way it learns new spells, and these formulas are transferred from a slain familiar to a new familiar in the same way spells are.\nDuring your daily preparations, you can create one temporary oil or potion using a formula you know. If you have master proficiency in spell DC, you can create a batch of two temporary oils or potions during your daily preparations, and if you have legendary proficiency, you can create a batch of three. Any items you create this way become inert bottles of liquid the next time you make your daily preparations, and any remaining effects of the temporary items end. A temporary oil or potion has no value.' },
      { name: 'Counterspell', level: 1, action: 'R', desc: 'Trigger - A creature Casts a Spell that you have prepared\nWhen a foe Casts a Spell and you can see its manifestations, you can use your magic to disrupt it. You expend a prepared spell to counter the triggering creature’s casting of that same spell. You lose your spell slot as if you had cast the triggering spell. You then attempt to counteract the triggering spell.\nSpecial - This feat has the trait corresponding to the tradition of spells you cast (arcane, divine, primal, or occult).' },
      { name: 'Reach Spell', action: '1', level: 1, desc: 'You can extend your spells’ range. If the next action you use is to Cast a Spell that has a range, increase that spell’s range by 30 feet. As is standard for increasing spell ranges, if the spell normally has a range of touch, you extend its range to 30 feet.' },
      { name: 'Widen Spell', action: '1', level: 1, desc: 'You manipulate the energy of your spell, causing it to spread out and affect a wider area. If the next action you use is to Cast a Spell that has an area of a burst, cone, or line and does not have a duration, increase the area of that spell. Add 5 feet to the radius of a burst that normally has a radius of at least 10 feet (a burst with a smaller radius is not affected). Add 5 feet to the length of a cone or line that is normally 15 feet long or smaller, and add 10 feet to the length of a larger cone or line.' },
      { name: "Witch's Armaments", level: 1, desc: 'Your patron’s power changes your body to ensure you are never defenseless. You gain one of the following unarmed attacks.\nEldritch Nails - Your nails are supernaturally long and sharp. You gain a nails unarmed attack that deals 1d6 slashing damage, is in the brawling group, and has the agile and unarmed traits.\nIron Teeth - With a click of your jaw, your teeth transform into long metallic points. You gain a jaws unarmed attack that deals 1d8 piercing damage and is in the brawling group.\nLiving Hair - You can instantly grow or shrink your hair, eyebrows, beard, or mustache by up to several feet and manipulate your hair for use as a weapon, though your control isn’t fine enough for more dexterous tasks. You gain a hair unarmed attack that deals 1d4 bludgeoning damage; is in the brawling group; and has the agile, disarm, finesse, trip, and unarmed traits.\nSpecial - You can take this feat more than once, gaining a different unarmed attack each time.' },
      { name: 'Basic Lesson', level: 2, desc: 'Your patron grants you a special lesson, revealing a hidden facet of its nature. Choose a basic lesson from the list here. You gain its associated hex, and your familiar learns the associated spell.' },
      { name: 'Cantrip Expansion', level: 2, desc: 'Study broadens your range of simple spells.\nPrepared Caster (Cleric, Wizard, etc.) - You can prepare two additional cantrips each day.\nSpontaneous Caster (Bard, Sorcerer, etc.) - Add two additional cantrips from your spell list to your repertoire.' },
      { name: 'Conceal Spell', action: '1', level: 2, desc: 'Through sheer mental effort, you can simplify the incantations and gestures needed to spellcast, leaving them barely noticeable. If the next action you use is to Cast a Spell, the spell gains the subtle trait, hiding the shining runes, sparks of magic, and other manifestations that would usually give away your spellcasting. The trait hides only the spell’s spellcasting actions and manifestations, not its effects, so an observer might still see a ray streak out from you or see you vanish into thin air.' },
      { name: 'Enhanced Familiar', level: 2, desc: 'You infuse your familiar with additional primal energy, increasing its abilities. You can select four familiar or master abilities each day, instead of two.\nSpecial - [Witch] Add the bonus familiar abilities you gain for being a witch to this amount. [Wizard] If your arcane thesis is improved familiar attunement, your familiar’s base number of familiar abilities, before adding any extra abilities from the arcane thesis, is four.' },
      { name: "Familiar's Language", level: 2, desc: 'You’ve learned to speak with your familiar and other creatures like it. You can ask questions of, receive answers from, and use the Diplomacy skill with creatures of the same family of animals as your familiar. For example, if your familiar were a cat, you could gain the effects of speak with animals for any felines (including leopards, lions, and tigers, among others). This ability doesn’t make them more friendly than normal. If your familiar ever changes to a different creature, you can’t use this ability for 1 week while you absorb your new familiar’s language.\nSpecial - This feat has the trait corresponding to the tradition of spells you cast (arcane, divine, occult, or primal).' },
      { name: 'Rites of Convocation', level: 4, desc: 'Your patron grants you the power to summon other creatures to aid you. Choose one summon spell (such as summon animal, summon construct, and so forth) that appears on the spell list of your spellcasting tradition. You can spend 10 minutes in communion with your familiar to replace one spell you’ve prepared in one of your witch spell slots with the spell you chose, heightened to the same rank. The spell you replaced must be of at least the summon spell’s minimum spell rank.' },
      { name: 'Sympathetic Strike', level: 4, action: '1', reqFeats: ["Witch's Armaments"], desc: 'Frequency - once per round\nYou collect your patron’s magic into one of your witch armaments, causing them to shine with runes, light, or another signifier of your patron. Make an unarmed Strike with one with your witch’s armaments. If you hit, you establish a sympathetic link with the target, making it easier for your patron to affect them. Until the beginning of your next turn, the target takes a –1 circumstance penalty to its saves against your hexes, or a –2 penalty if the triggering Strike was a critical hit.' },
      { name: 'Ceremonial Knife', level: 6, desc: 'You have prepared a special knife to direct energies when spellcasting. During your daily preparations, you and your familiar can perform a short ritual over a weapon in the knife group—typically a dagger. This causes the knife to function as a magic wand, containing any one 1st-rank spell your familiar knows. You, and only you, can Activate the knife to Cast the Spell within it, as normal for a wand. You can attempt to overcharge the knife, and this can break or destroy the knife as normal. You can have only one ceremonial knife at a time.\nAt 8th level, and every 2 levels thereafter, the maximum rank of spell your ceremonial knife can hold increases by 1.' },
      { name: 'Greater Lesson', level: 6, desc: 'Your patron grants you greater knowledge. Choose a greater or basic lesson from the list here. You gain its associated hex, and your familiar learns the associated spell.' },
      { name: 'Steady Spellcasting', level: 6, desc: 'You don’t lose spells easily. If a reaction would disrupt your spellcasting action, attempt a DC 15 flat check. If you succeed, your action isn’t disrupted.' },
      { name: "Witch's Charge", level: 6, desc: 'You forge a magical link with another creature, granting you awareness of that creature’s condition and creating a conduit for spellcasting. During your daily preparations, you can designate one willing creature as your charge. You are always aware of your charge’s direction from you, its distance from you, and any conditions affecting it. In addition, you can cast spells with a range of touch on your charge from a range of 30 feet. These effects persist until your next daily preparations.\nSpecial - This feat has the trait corresponding to the tradition of spells you cast (arcane, divine, occult, or primal).' },
      { name: 'Incredible Familiar', level: 8, reqFeats: ['Enhanced Familiar'], desc: 'Your familiar is imbued with even more magic than other familiars. You can select a base of six familiar or master abilities each day, instead of four.\nSpecial - Add the bonus familiar abilities you gain for being a witch to this amount.' },
      { name: 'Murksight', level: 8, desc: 'Your vision pierces through non-magical fog, mist, rain, and snow. You don’t take circumstance penalties to ranged attacks or Perception checks caused by non-magical precipitation, and your targeted attacks don’t require a flat check to succeed against a target concealed only by such effects.' },
      { name: 'Spirit Familiar', level: 8, reqPatronTradition: ['Divine', 'Occult'], desc: 'Your familiar can subsume its body to become pure spirit. Your familiar gains the Shed Spirit activity.\nShed Spirit - 2 Actions (spirit)\nFrequency - once per 10 minutes;\nEffect - Your familiar’s spirit exits its body, leaving its empty shell behind, before flying at an enemy within 20 feet and dealing 6d6 spirit damage, with a basic Will save against your spell DC. If the familiar dealt damage, it then flies to an ally within 30 feet of the enemy, restoring Hit Points equal to half the damage dealt. Your familiar then re-forms in its original square. At 9th level, and every 2 levels thereafter, the attack deals an additional 2d6 damage.' },
      { name: 'Stitched Familiar', level: 8, reqPatronTradition: ['Arcane', 'Primal'], desc: 'Your familiar can shed its material form, becoming a mass of animated magic. Your familiar gains the Stitching Strike activity.\nStitching Strike - 2 Actions\nFrequency - once per 10 minutes;\nEffect - Your familiar unravels into magical fibers that encompass an enemy within 30 feet and deal 6d6 slashing damage, with a basic Reflex save against your spell DC. On a failure, the target is also immobilized for 1 round or until it Escapes against your spell DC. Your familiar then re-forms in its original square. At 9th level, and every 2 levels thereafter, the attack deals an additional 2d6 damage.' },
      { name: "Witch's Bottle", level: 8, reqFeats: ['Cauldron'], desc: 'You spend 10 minutes and 1 Focus Point brewing a special potion containing the power of one of your hexes that targets a creature. A creature that consumes this potion is targeted by the hex. If the hex has a sustained duration and you have cackle, you can cast cackle into the bottle just before you seal it. If you do, the hex’s duration is extended as if you had cast cackle the round after the hex was cast (typically this extends the duration by 1 round). Your cackling laugh sounds out when the potion is unsealed.\nAny potion you create this way loses its power the next time you make your daily preparations. While the potion is in your possession, you can render it inert using a single action that has the concentrate trait. You can’t regain the Focus Point you spent to create the potion (or the Focus Point you spent to cast cackle) until the potion is consumed or loses its magic.' },
      { name: 'Double, Double', level: 10, reqFeats: ['Cauldron'], desc: 'For each temporary oil or potion you brew during your daily preparations, you brew two copies of it. This allows you to brew two temporary oils or potions each day, four if you have master proficiency in spell DC, or six if you have legendary proficiency' },
      { name: 'Major Lesson', level: 10, desc: 'Your patron grants you even greater secrets. Choose a major, greater, or basic lesson from the list here. You gain its associated hex, and your familiar learns the associated spell.\nSpecial - You can select this feat a second time if you’re 14th level or higher, and a third time if you’re 18th level or higher. Choose a different lesson each time.' },
      { name: 'Quickened Casting', action: 'F', level: 10, desc: 'Frequency - once per day\nIf your next action is to cast a cantrip or a spell that is at least 2 ranks lower than the highest-rank spell slot you have, reduce the number of actions to cast it by 1 (minimum 1 action).\nSpecial - This feat can only be used on a cantrip or spell that is at least 2 ranks lower than the highest-rank spell slot from the class or archetype matching the one you gained this feat from.' },
      { name: "Witch's Communion", level: 10, reqFeats: ["Witch's Charge"], desc: 'You can keep watch over multiple charges. Each day during your preparations, you can designate a number of charges equal to your Intelligence modifier instead of just one.' },
      { name: 'Coven Spell', level: 12, action: 'R', desc: 'Trigger - An ally within 30 feet Casts a Spell\nYou rhyme with your ally’s incantations or echo their movements, linking your magic to empower their spell in one of two ways:\nIf their spell deals damage and doesn’t have a duration, you grant that spell a status bonus to damage equal to its rank.\nIf their spell doesn’t have a spellshape effect applied to it, apply the effects of any one spellshape feat you know to the spell. The spellshape feat must be one that can be applied to the triggering spell, and you must be able to use it (for instance, if the spellshape feat is usable only a limited number of times per day).' },
      { name: 'Hex Focus', level: 12, desc: 'Your patron’s teachings have allowed you to achieve a deeper focus. Whenever you Refocus, completely refill your focus pool.' },
      { name: "Witch's Broom", level: 12, desc: 'A broom is the only steed you need to fly through the night sky. During your daily preparations, you can anoint a single broom, staff, polearm, or similarly shaped object with a flying ointment made of special herbs and oils. Until the next time you make your daily preparations, it gains the magical trait, and you can ride on it while you’re holding it with at least 1 hand. It moves at a fly Speed of 20 feet. The broom takes a –10-foot penalty to its Speed if laden with more than 20 Bulk, and crashes to the ground if it carries more than 30 Bulk. The broom can’t be controlled by anyone but you. If you anoint a weapon or other held item, you can’t ride the broom and wield it at the same time.\nYou can Craft your broomstick into a flying broomstick as though you had the formula for that item. If you anoint an item that’s already a flying broomstick, the broom gains a +10-foot status bonus to its Speed and you can choose whether it works for anyone or only you.' },
      { name: "Patron's Presence", level: 14, desc: 'Your patron can direct its attention through your familiar, and its mere presence becomes an ominous weight on the minds of other beings to distract them and blot out their magic. Your familiar gains the following activity.\nPatron’s Presence - 2 Actions (aura)\nFrequency - once per hour;\nEffect - A palpable weight extends from your familiar in a 15-foot emanation. Enemies who enter or start their turn within the aura must succeed at a Will save against your spell DC or become stupefied 2 as long as they remain within the aura, or stupefied 3 on a critical failure. The aura lasts until the end of your next turn, but the familiar can Sustain it up to 1 minute.' },
      { name: 'Reflect Spell', level: 14, reqFeats: ['Counterspell'], desc: 'When you successfully use Counterspell to counteract a spell that affects targeted creatures or an area, you can turn that spell’s effect back on its caster. When reflected, the spell affects only the original caster, even if it’s an area spell or it would normally affect more than one creature. The original caster can attempt a save and use other defenses against the reflected spell as normal.' },
      { name: 'Rites of Transfiguration', level: 14, desc: 'You can adapt your patron’s power to transform other creatures into forms more befitting their behavior or your whims. Your familiar learns cursed metamorphosis, even if cursed metamorphosis isn’t on your tradition’s spell list. By spending 10 minutes in communion with your familiar, you can replace one spell of 6th-rank or higher you’ve prepared in one of your witch spell slots with a cursed metamorphosis spell of the same rank.' },
      { name: 'Effortless Concentration', action: 'F', level: 16, desc: 'Trigger - Your turn begins\nYou can maintain a spell with hardly a thought. You immediately gain the effects of the Sustain action, allowing you to extend the duration of one of your active spells.\nSpecial - This can only be used on a cantrip or spell from the class matching the one you gained this feat from.' },
      { name: 'Siphon Power', action: 'F', level: 16, desc: 'Trigger - once per day\nRequirements - You haven’t acted yet on your turn\nYou draw upon the reservoir of your patron’s magic that resides within your familiar. During your turn, you can cast one spell your familiar knows that was granted by your patron or lessons without spending a spell slot to do so (or even having it prepared). The spell must be at least 1 rank lower than your highest-rank witch spell slot.\nSpecial - This feat has the trait corresponding to the tradition of spells you cast (arcane, divine, occult, or primal).' },
      { name: 'Split Hex', action: '1', level: 18, desc: 'You siphon some of the power from an offensive hex you cast to direct it at a second target as well. If the next action you use is to Cast a Spell to cast a harmful hex with a single target, reduce its rank by 2 (making it 2 ranks lower than the maximum spell rank you can cast). If you do, you can select a second target for that hex to affect.' },
      { name: "Patron's Claim", level: 18, desc: 'Your patron partially manifests itself through your familiar to claim a foe’s power for its own. Your familiar gains the following activity.\nPatron’s Claim - 2 Actions\nFrequency - once per hour;\nEffect - Your familiar’s mouth opens impossibly wide before your patron’s grasping limb stretches forth from it at a creature within 30 feet, dealing 10d10 spirit damage with a basic Fortitude save against your spell DC. If the creature fails its save and takes damage, it is also drained 2 (or drained 4 on a critical failure) and you regain 1 Focus Point, up to your usual maximum, as your patron grants you additional magic in exchange for your gift of your opponent’s spirit.' },
      { name: 'Hex Master', level: 20, desc: 'You embody the link to your patron so completely that you can cast your hexes in rapid succession. You are no longer limited to casting only a single hex each turn. In addition, when you cast cackle to sustain a hex, you gain the effects of Sustain for all your active hexes that have a duration of sustained.' },
      { name: "Patron's Truth", level: 20, desc: 'You have mastered the greatest secrets of your patron’s magic and learned a fundamental truth about your patron, even if their identity still remains a mystery. You gain an additional 10th-rank spell slot.' },
      { name: "Witch's Hut", level: 20, desc: 'Your home is an animated structure that obeys your commands. By performing a rite that takes 1 day, you create an animated object from a hut, small house, covered wagon, tent, or similar construction of up to Huge size.\nThe hut uses your AC, saving throw modifiers, and Perception modifier and has 150 HP and Hardness 10. It has the construct armor ability, meaning once it’s reduced to less than half its Hit Points, or immediately upon being damaged by a critical hit, its AC is reduced by 4 until it is repaired.\nThe hut can’t attack or attempt skill checks. You can give the hut a command as a single action, which has the auditory and concentrate traits; after 1 round of reconfiguring itself, the hut then follows that command until you give it a different command.\nGuard - The hut watches for trespassers within 120 feet using your Perception modifier and screams if it spots any.\nHide - The hut appears to be a normal, mundane object of its type. This is a 10th-rank illusion effect.\nLeap - The hut spins around or leaps into the air, then casts 10th rank teleport, transporting itself and all creatures within it.\nLock - With a slam, each entrance to the hut becomes sealed with a lock spell. You can give this command again to unlock its entrances.\nMove - The hut gains a Speed of 60 feet, growing giant bird or bone legs, if necessary, and follows an extremely basic movement command you give it, such as “follow me” or “move that direction.” While perfectly suitable for overland travel, the hut’s broad movements and 1-round delay on response time are too imprecise to predictably direct in a combat encounter or other situation where seconds and precise locations count.\nYou can have only one witch’s hut at a time. If you animate a new hut, your previous hut immediately reverts to its original, mundane form. If you die, the hut continues following the last order you gave it indefinitely.' },
    ] },
];

